PRAGMA foreign_keys = ON;
BEGIN;

-- The list number the book prints before an item («٢- ») and the count bracket
-- it prints after it («[ثلاثًا]») shown inside `body`, exactly as printed (#227).
-- Numbers in Eastern Arabic digits followed by «- »; a body that opens with a
-- QuranText line gets its number on a line of its own, since that line is
-- replaced by the verses. Count brackets kept in `source` move to the end of
-- `body`. The counter is unchanged. `search` is build_search(body).

-- title 1
UPDATE contents SET body = '١- أصبحنا على فِطْرَةِ الإسلامِ، وكَلِمَةِ الإخلاصِ، ودِينِ نَبِيِّنَا مُحمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ومِلَّةِ أَبِينَا إبراهيمَ، حنيفًا مُسلِمًا، وما كَانَ مِنَ المُشْرِكِينَ', search = '١- أصبحنا على فطرة الإسلام وكلمة الإخلاص ودين نبينا محمد صلى الله عليه وسلم وملة أبينا إبراهيم حنيفا مسلما وما كان من المشركين' WHERE id = 1;
UPDATE contents SET body = '٢- رَضِيتُ باللهِ رَبًّا، وبالإسلامِ دِينًـا، وبمُحمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّـا', search = '٢- رضيت بالله ربا وبالإسلام دينا وبمحمد صلى الله عليه وسلم نبيا' WHERE id = 2;
UPDATE contents SET body = '٣- اللهم بكَ أصبحنا، وبكَ أمسينا، وبكَ نحيا، وبك نموتُ، وإليكَ النشورُ', search = '٣- اللهم بك أصبحنا وبك أمسينا وبك نحيا وبك نموت وإليك النشور' WHERE id = 3;
UPDATE contents SET body = '٤- لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قدير', search = '٤- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير' WHERE id = 4;
UPDATE contents SET body = '٥- اللهم إنِّي أسألُكَ علمًا نافعًا، ورِزْقًا طَيِّبًا، وعَمَلًا مُتَقَبَّلًا', search = '٥- اللهم إني أسألك علما نافعا ورزقا طيبا وعملا متقبلا' WHERE id = 11;
UPDATE contents SET body = '٦- يا حَيُّ يا قَيُّومُ برحمتِك أستغيثُ، أصْلِحْ لي شأني كُلَّه، ولا تَكِلْني إلى نفسي طَرْفَةَ عينٍ أَبَدًا', search = '٦- يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين أبدا' WHERE id = 5;
UPDATE contents SET body = '٧- آية الكرسي: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ
QuranText[(2:255:255)]', search = '٧- آية الكرسي أعوذ بالله من الشيطان الرجيم 2255255' WHERE id = 6;
UPDATE contents SET body = '٨- أصْبَحْنَا، وأصبحَ الملكُ للهِ، والحمدُ للهِ، لا إله إلا اللهُ وحده، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ، رَبِّ أسألُكَ خيرَ ما في هذا اليومِ، وخيرَ ما بعدَه، وأعوذُ بكَ مِن شَرِّ ما في هذا اليومِ، وشَرِّ ما بعدَه، رَبِّ أعوذُ بِكَ من الكَسَلِ وسُوءِ الكِبَرِ، رَبِّ أعوذُ بكَ من عذابٍ في النَّارِ وعذابٍ في القَبْرِ', search = '٨- أصبحنا وأصبح الملك لله والحمد لله لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير رب أسألك خير ما في هذا اليوم وخير ما بعده وأعوذ بك من شر ما في هذا اليوم وشر ما بعده رب أعوذ بك من الكسل وسوء الكبر رب أعوذ بك من عذاب في النار وعذاب في القبر' WHERE id = 9;
UPDATE contents SET body = '٩- اللهم أنت ربي، لا إله إلَّا أنتَ، خلقَتَني، وأنا عبدُك، وأنا على عَهْدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بكَ مِنْ شَرِّ ما صنعتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وأبوءُ بذَنْبي، فَاغْفِرْ لي؛ فإنَّه لا يَغْفِرُ الذُّنُوبَ إلَّا أَنْتَ', search = '٩- اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت' WHERE id = 7;
UPDATE contents SET body = '١٠- اللهمَّ فاطِرَ السماواتِ والأرضِ، عالِمَ الغيبِ والشَّهادةِ، أشهد أن لا إله إلَّا أنت، رَبَّ كُلِّ شيءٍ ومَلِيكَه، أعوذُ بِكَ مِنْ شَرِّ نَفْسِي، ومِن شَرِّ الشيطانِ وشِرْكِه، وأن أَقْتَرِفَ على نفسي سُوءًا، أو أَجُرَّهُ إلى مُسْلِمٍ', search = '١٠- اللهم فاطر السماوات والأرض عالم الغيب والشهادة أشهد أن لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي ومن شر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم' WHERE id = 8;
UPDATE contents SET body = '١١- اللهم إنِّي أسألُكَ العافيةَ في الدنيا والآخِرةِ، اللهم إنِّي أسألُكَ العفوَ والعافيةَ في ديني ودُنْيايَ، وأهلي، ومالي، اللهم اسْتُرْ عوراتي، وآمِن رَّوْعاتي، اللهم احفظني من بين يَدَيَّ، ومِن خَلْفي، وعن يَميني، وعن شِمالي، ومِن فوقي، وأعوذُ بعظَمَتِكَ أنْ أُغْتَالَ مِنْ تحتي', search = '١١- اللهم إني أسألك العافية في الدنيا والآخرة اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي اللهم استر عوراتي وآمن روعاتي اللهم احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي' WHERE id = 10;
UPDATE contents SET body = '١٢- أصبحتُ أُثْني عليكَ حَمْدًا، وأشهدُ أن لا إله إلا الله [ثلاث مرَّات]', search = '١٢- أصبحت أثني عليك حمدا وأشهد أن لا إله إلا الله ثلاث مرات' WHERE id = 12;
UPDATE contents SET body = '١٣- باسمِ اللهِ الذي لا يَضُرُّ مع اسمِه شيءٌ في الأرضِ ولا في السماءِ، وهو السَّمِيعُ العليمُ [ثلاثَ مَرَّاتٍ]', search = '١٣- باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات' WHERE id = 13;
UPDATE contents SET body = '١٤- سُبْحانَ اللهِ عدَدَ خَلْقِه، سُبْحانَ اللهِ رِضَا نفسِه، سُبْحانَ اللهِ زِنَةَ عَرْشِه، سُبْحانَ اللهِ مِدادَ كَلِماتِه [ثلاثَ مرَّاتٍ]
أو: سبحانَ اللهِ وبحمدِهِ عددَ خَلْقِه، ورِضا نفسِه، وزِنَةَ عَرْشِه، ومِدادَ كَلِماتِه [ثلاثَ مرَّاتٍ]', search = '١٤- سبحان الله عدد خلقه سبحان الله رضا نفسه سبحان الله زنة عرشه سبحان الله مداد كلماته ثلاث مرات أو سبحان الله وبحمده عدد خلقه ورضا نفسه وزنة عرشه ومداد كلماته ثلاث مرات' WHERE id = 14;
UPDATE contents SET body = '١٥- اللهم عافِني في بدني، اللهم عافِني في سَمْعِي، اللهم عافِني في بصري، لا إله إلَّا أنْتَ [ثلاثَ مرَّاتٍ]', search = '١٥- اللهم عافني في بدني اللهم عافني في سمعي اللهم عافني في بصري لا إله إلا أنت ثلاث مرات' WHERE id = 15;
UPDATE contents SET body = 'اللهم إنِّي أعوذُ بِكَ مِنَ الكُفْرِ والفقرِ، اللهم إنِّي أعوذُ بِكَ من عذابِ القبرِ، لا إله إلَّا أنْتَ [ثلاثَ مرَّاتٍ]', search = 'اللهم إني أعوذ بك من الكفر والفقر اللهم إني أعوذ بك من عذاب القبر لا إله إلا أنت ثلاث مرات' WHERE id = 16;
UPDATE contents SET body = '١٦- سُوَر: (الإخلاص)، و(الفلق)، و(الناس) [ثلاثَ مرَّاتٍ]', search = '١٦- سور الإخلاص و الفلق و الناس ثلاث مرات' WHERE id = 17;
UPDATE contents SET body = '١٧- ﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾ [سَبْعَ مرَّاتٍ]', search = '١٧- ﴿ حسۡبي ٱلله لآ إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾ سبع مرات' WHERE id = 18;
UPDATE contents SET body = '١٨- لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، يُحْيِي ويُمِيتُ، وهُوَ على كُلِّ شيءٍ قديرٌ [عَشْرَ مَرَّاتٍ]', search = '١٨- لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير عشر مرات' WHERE id = 19;
UPDATE contents SET body = '١٩- أستغفِرُ اللهَ [مئةَ مَرَّةٍ]', search = '١٩- أستغفر الله مئة مرة' WHERE id = 23;
UPDATE contents SET body = '٢٠- سبحانَ اللهِ وبحمدِهِ [مئةَ مَرَّةٍ أو أكثر]
أو: سبحانَ اللهِ العظيمِ وبحمدِهِ [مئةَ مَرَّةٍ أو أكثر]', search = '٢٠- سبحان الله وبحمده مئة مرة أو أكثر أو سبحان الله العظيم وبحمده مئة مرة أو أكثر' WHERE id = 21;
UPDATE contents SET body = '٢١- سبحانَ اللهِ [مئةَ مَرَّةٍ أو أكثر]', search = '٢١- سبحان الله مئة مرة أو أكثر' WHERE id = 24;
UPDATE contents SET body = 'الحمدُ للهِ [مئةَ مَرَّةٍ أو أكثر]', search = 'الحمد لله مئة مرة أو أكثر' WHERE id = 25;
UPDATE contents SET body = 'اللهُ أكبرُ [مئةَ مَرَّةٍ أو أكثر]', search = 'الله أكبر مئة مرة أو أكثر' WHERE id = 26;
UPDATE contents SET body = 'لا إله إلا الله وحده، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ [مئةَ مَرَّةٍ أو أكثر]', search = 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير مئة مرة أو أكثر' WHERE id = 27;
UPDATE contents SET body = 'أو يقول: لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ [مئةَ مَرَّةٍ]', search = 'أو يقول لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير مئة مرة' WHERE id = 1233;
UPDATE contents SET body = '٢٢- سبحان الله وبحمده،
سُبحانَكَ اللهمَّ وبحمدِكَ،
أشهدُ أن لا إله إلا أنت،
أستغفِرُكَ، وأتوبُ إليكَ', search = '٢٢- سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك' WHERE id = 28;
