UPDATE contents SET body = '٢- لا إلهَ إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قدير', search = '٢- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير' WHERE id = 33;
