UPDATE contents SET body = '٤- آية الكرسي: أَعُوذُ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ
QuranText[(2:255:255)]', search = '٤- آية الكرسي أعوذ بٱلله من ٱلشيطن ٱلرجيم 2255255' WHERE id = 35;
UPDATE contents SET body = '٥- أمسينا، وأمسى المُلْكُ لله، والحمدُ لله، لا إله إلا اللهُ وحدَهُ، لا شريكَ له، له المُلْكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ، رَبِّ أسألُكَ خيرَ ما في هذه الليلةِ، وخيرَ ما بعدَها، وأعوذُ بِكَ مِنْ شَرِّ ما في هذه الليلةِ، وشَرِّ ما بعدَها، رَبِّ أعوذُ بِكَ من الكَسَلِ وسوءِ الكِبَرِ، رَبِّ أعوذُ بِكَ من عذابٍ في النَّارِ، وعذابٍ في القَبْرِ', search = '٥- أمسينا وأمسى الملك لله والحمد لله لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير رب أسألك خير ما في هذه الليلة وخير ما بعدها وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها رب أعوذ بك من الكسل وسوء الكبر رب أعوذ بك من عذاب في النار وعذاب في القبر' WHERE id = 38;
UPDATE contents SET body = '٦- اللهم أنتَ رَبِّي، لا إلهَ إلا أنتَ، خَلَقْتَنِي، وأنا عبدُك، وأنا على عَهْدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بِكَ مِنْ شَرِّ ما صنعتُ، أبوءُ لكَ بنعمتِكَ عَلَيَّ، وأبوءُ بذنبي، فاغفِرْ لِي؛ فإنَّه لا يَغْفِرُ الذنوبَ إلَّا أَنْتَ', search = '٦- اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت' WHERE id = 36;
UPDATE contents SET body = '٧- اللهم فاطِرَ السماواتِ والأرضِ، عالِمَ الغيبِ والشَّهادةِ، أشهد أن لا إله إلَّا أنْتَ، رَبَّ كُلِّ شيءٍ ومَلِيكَه، أعوذُ بِكَ من شَرِّ نفسي، وشَرِّ الشيطانِ وشِرْكِه، وأن أقتَرِفَ على نفسي سُوءًا، أو أجرَّه إلى مُسْلِمٍ', search = '٧- اللهم فاطر السماوات والأرض عالم الغيب والشهادة أشهد أن لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي وشر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم' WHERE id = 37;
UPDATE contents SET body = '٨- اللهم إنِّي أسألُكَ العافيةَ في الدنيا والآخرة، اللهم إنِّي أسألُكَ العفوَ والعافيةَ في ديني، ودُنْيايَ، وأهلي، ومالي، اللهم اسْتُرْ عَوْراتي، وآمِن رَّوْعاتي، اللهم احفظني مِن بينِ يدَيَّ، ومِن خَلْفي، وعن يَميني، وعن شِمالي، ومِن فوقي، وأعوذُ بعَظَمَتِكَ أَنْ أُغْتالَ مِنْ تحتي', search = '٨- اللهم إني أسألك العافية في الدنيا والآخرة اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي اللهم استر عوراتي وآمن روعاتي اللهم احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي' WHERE id = 39;
