UPDATE contents SET body = '١- سبحانَ رَبِّيَ العظيمِ [ثلاثًا أو أكثر]', search = '١- سبحان ربي العظيم ثلاثا أو أكثر', source = 'أذكار الركوع. (ص97)

حاشية: مقصود الذكر هنا تعظيم الرب سبحانه وتعالى بأيِّ لفظٍ كان، ولكن الأفضل أن يجمع بين هذه الأذكار كلها إن تمكَّن من ذلك بحيث لا يشق على غيره، ويُقَدِّمُ التسبيحَ منها، فإن أراد الاقتصار فيستحب التسبيحُ، وأدنى الكمال منه ثلاث تسبيحات، ولو اقتصر على مرة كان فاعلًا لأصل التسبيح، ويستحب إذا اقتصر على البعض أن يفعل في بعض الأوقات بعضَها، وفي وقتٍ آخر بعضًا آخر، وهكذا يفعل في الأوقات حتى يكون فاعلًا لجميعها، وكذا ينبغي أن يفعل في أذكار جميع الأبواب.' WHERE id = 920;
