UPDATE contents SET body = '٧- اللهم لك ركعتُ، وبك آمنتُ، ولك أسلمتُ، أنت رَبِّي، خَشَعَ لَكَ سَمْعِي وبَصَرِي، ومُخِّي وعَظْمي وعَصَبِي، وما استَقَلَّتْ به قَدَمِي للهِ رَبِّ العالمين', search = '٧- اللهم لك ركعت وبك آمنت ولك أسلمت أنت ربي خشع لك سمعي وبصري ومخي وعظمي وعصبي وما استقلت به قدمي لله رب العالمين' WHERE id = 926;
UPDATE contents SET body = '٨- اللهم لك ركعتُ، وبك آمنتُ، ولك أسلمتُ، وعليك توكلتُ، أنت ربي، خَشَعَ سمعي وبصري، ودمي ولحمي، وعَظْمي وعَصَبِي للهِ رَبِّ العالمين', search = '٨- اللهم لك ركعت وبك آمنت ولك أسلمت وعليك توكلت أنت ربي خشع سمعي وبصري ودمي ولحمي وعظمي وعصبي لله رب العالمين' WHERE id = 927;
