UPDATE contents SET body = '٢- أو: اللهم رَبَّنا ولكَ الحمدُ', search = '٢- أو اللهم ربنا ولك الحمد' WHERE id = 931;
UPDATE contents SET body = '٣- أو: رَبَّنا ولك الحمدُ، حمدًا كثيرًا طيبًا مُبَارَكًا فيه، مباركًا عليه، كما يُحِبُّ رَبُّنا ويرضى', search = '٣- أو ربنا ولك الحمد حمدا كثيرا طيبا مباركا فيه مباركا عليه كما يحب ربنا ويرضى' WHERE id = 932;
UPDATE contents SET body = '٤- أو: رَبَّنا لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، وملءَ ما بينهما، وملءَ ما شِئْتَ مِنْ شيءٍ بَعْدُ، أهلَ الثناءِ والمجدِ، أحقُّ ما قال العبدُ، وكلُّنا لك عبدٌ، اللهم لا مانعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منك الجَدُّ', search = '٤- أو ربنا لك الحمد ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد' WHERE id = 933;
UPDATE contents SET body = '٥- اللهم لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، ومِلْءَ ما شِئْتَ مِنْ شيءٍ بَعْدُ، اللهم طَهِّرْني بالثلجِ والبَرَدِ والماءِ البارد، اللهم طَهِّرْني من الذنوبِ والخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ', search = '٥- اللهم لك الحمد ملء السماوات وملء الأرض وملء ما شئت من شيء بعد اللهم طهرني بالثلج والبرد والماء البارد اللهم طهرني من الذنوب والخطايا كما ينقى الثوب الأبيض من الدنس' WHERE id = 934;
UPDATE contents SET body = '٦- أو يقول: «لِرَبِّيَ الحمدُ، لِرَبِّيَ الحمدُ»، ويُكْرِرها في قيام الليل طويلًا', search = '٦- أو يقول «لربي الحمد لربي الحمد» ويكررها في قيام الليل طويلا' WHERE id = 935;
