UPDATE contents SET body = '٧- اللهم اغفرْ لي ذنبي كُلَّه، ودِقَّه وجِلَّه، وأوَّلَه وآخِرَه، وعلانِيَتَه وسِرَّه', search = '٧- اللهم اغفر لي ذنبي كله ودقه وجله وأوله وآخره وعلانيته وسره' WHERE id = 109;
UPDATE contents SET body = '٨- اللهم إني أعوذُ برِضاكَ من سَخَطِكَ، وأعوذُ بمعافاتِكَ من عقوبتِكَ، وأعوذُ بك منك، لا أُحصي ثناءً عليك، أنتَ كما أثنيتَ على نفسِكَ', search = '٨- اللهم إني أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك' WHERE id = 110;
UPDATE contents SET body = '٩- اللهم إني ظلمتُ نفسي ظُلمًا كثيرًا، ولا يغفرُ الذنوبَ إلا أنتَ، فاغفرْ لي مغفرةً مِن عندك، وارحمني إنك أنت الغفورُ الرحيم', search = '٩- اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم' WHERE id = 111;
UPDATE contents SET body = '١٠- اللهم لك سجدتُ، وبك آمنتُ، ولك أسلمتُ، وأنت ربي، سجدَ وجهي لِلَّذي خَلَقَهُ وصَوَّرَهُ، فأحسنَ صُوَرَه، وشَقَّ سَمْعَهُ وبَصَرَهُ، فتباركَ اللهُ أحسنُ الخالقين', search = '١٠- اللهم لك سجدت وبك آمنت ولك أسلمت وأنت ربي سجد وجهي للذي خلقه وصوره فأحسن صوره وشق سمعه وبصره فتبارك الله أحسن الخالقين' WHERE id = 112;
UPDATE contents SET body = '١١- سَجَدَ لك سَوادي وخيالي، وآمَنَ بك فؤادي، أبوءُ بنعمتِكَ عَلَيَّ، هَذِي يَدِي، وما جَنَيْتُ على نفسي', search = '١١- سجد لك سوادي وخيالي وآمن بك فؤادي أبوء بنعمتك علي هذي يدي وما جنيت على نفسي' WHERE id = 113;
UPDATE contents SET body = '١٢- اللهم اجعل في قلبي نورًا، وفي لساني نورًا، واجعل في سمعي نورًا، واجعل في بصري نورًا، واجعل مِن تحتي نورًا، واجعل مِن فوقي نورًا، وعن يميني نورًا، وعن يساري نورًا، واجعل أمامي نورًا، واجعل خلفي نورًا، واجعل في نفسي نورًا، وأعظِمْ لي نورًا', search = '١٢- اللهم اجعل في قلبي نورا وفي لساني نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من تحتي نورا واجعل من فوقي نورا وعن يميني نورا وعن يساري نورا واجعل أمامي نورا واجعل خلفي نورا واجعل في نفسي نورا وأعظم لي نورا' WHERE id = 114;
UPDATE contents SET body = '١٣- سبحانك اللهم وبحمدك، لا إله إلا أنت', search = '١٣- سبحانك اللهم وبحمدك لا إله إلا أنت' WHERE id = 115;
