UPDATE contents SET body = '١- رَبِّ اغفِرْ لي، رَبِّ اغفِرْ لي', search = '١- رب اغفر لي رب اغفر لي' WHERE id = 116;
UPDATE contents SET body = '٢- اللهم اغفر لي، وارحمني، واجْبُرْنِي، وارْفَعْنِي، واهْدِنِي، وعافِنِي، وارزقني', search = '٢- اللهم اغفر لي وارحمني واجبرني وارفعني واهدني وعافني وارزقني' WHERE id = 117;
UPDATE contents SET body = '١- سَجَدَ وجهي لِلَّذي خَلَقَهُ، وشَقَّ سمعَه وبَصَرَه بحوله وقُوَّتِه', search = '١- سجد وجهي للذي خلقه وشق سمعه وبصره بحوله وقوته' WHERE id = 118;
UPDATE contents SET body = '٢- اللَّهُمَّ اكتُبْ لي بها عِنْدَكَ أجرًا، وَضَعْ عنِّي بها وِزْرًا، واجعَلْها لي عِندَكَ ذُخرًا، وَتَقَبَّلْها مِنِّي كما تَقَبَّلْتَها من عَبْدِكَ داودَ', search = '٢- اللهم اكتب لي بها عندك أجرا وضع عني بها وزرا واجعلها لي عندك ذخرا وتقبلها مني كما تقبلتها من عبدك داود' WHERE id = 119;
-- title 14
UPDATE contents SET body = '١- التحياتُ للهِ، والصلواتُ والطيباتُ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا عبدُه ورسولُه', search = '١- التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله' WHERE id = 120;
UPDATE contents SET body = '٢- التحياتُ المباركاتُ الصلواتُ الطيباتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا رسولُ اللهِ', search = '٢- التحيات المباركات الصلوات الطيبات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا رسول الله' WHERE id = 936;
UPDATE contents SET body = '٣- التحياتُ للهِ، والصلواتُ والطيباتُ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه', search = '٣- التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله' WHERE id = 937;
UPDATE contents SET body = '٤- التحياتُ الطيباتُ الصلواتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه', search = '٤- التحيات الطيبات الصلوات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله' WHERE id = 938;
UPDATE contents SET body = '٥- التحياتُ للهِ، الزاكياتُ للهِ، الطيباتُ للهِ، الصلواتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا عبدُه ورسولُه', search = '٥- التحيات لله الزاكيات لله الطيبات لله الصلوات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله' WHERE id = 939;
UPDATE contents SET body = '١- اللهمَّ صلِّ على محمدٍ وعلى آلِ محمدٍ، كما صليتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، اللهمَّ باركْ على محمدٍ وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', search = '١- اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد' WHERE id = 121;
UPDATE contents SET body = '٢- اللهمَّ صلِّ على محمدٍ وعلى أهلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما صليتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ وعلى آلِ بيتِه، وعلى أزواجِه وذريتِه، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', search = '٢- اللهم صل على محمد وعلى أهل بيته وعلى أزواجه وذريته كما صليت على آل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل بيته وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد' WHERE id = 940;
UPDATE contents SET body = '٣- اللهمَّ صلِّ على محمدٍ، وعلى آلِ محمدٍ، كما صَلَّيتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', search = '٣- اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وآل إبراهيم إنك حميد مجيد' WHERE id = 941;
UPDATE contents SET body = '٤- اللَّهُمَّ صَلِّ على مُحَمَّدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما باركتَ على آلِ إبراهيمَ في العالمينَ، إنَّكَ حَمِيدٌ مَجِيدٌ', search = '٤- اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد' WHERE id = 942;
UPDATE contents SET body = '٥- اللَّهُمَّ صَلِّ على محمدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ محمدٍ، كما باركْتَ على إبراهيمَ، وعلى آلِ إبراهيمَ', search = '٥- اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم' WHERE id = 943;
UPDATE contents SET body = '٦- اللهم صَلِّ على محمدٍ وعلى أزواجِهِ وذُرِّيَّتِهِ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ وعلى أزواجِهِ وذريتِهِ، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', search = '٦- اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد' WHERE id = 122;
UPDATE contents SET body = '٧- اللهم صَلِّ على محمدٍ، وعلى آلِ محمدٍ، وبارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما صَلَّيْتَ وباركتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حَميدٌ مجيدٌ', search = '٧- اللهم صل على محمد وعلى آل محمد وبارك على محمد وعلى آل محمد كما صليت وباركت على إبراهيم وآل إبراهيم إنك حميد مجيد' WHERE id = 944;
-- title 15
UPDATE contents SET body = '١- اللهم إنِّي أعوذُ بك من عذابِ جَهَنَّمَ، ومن عذابِ القبرِ، ومن فتنةِ المحيا والمماتِ، ومن شَرِّ فتنةِ المسيحِ الدَّجَّالِ', search = '١- اللهم إني أعوذ بك من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن شر فتنة المسيح الدجال' WHERE id = 123;
UPDATE contents SET body = '٢- اللهم إني أعوذُ بك من عذابِ القبرِ، وأعوذُ بك من فتنةِ المسيحِ الدجالِ، وأعوذُ بك من فتنةِ المحيا والمماتِ، اللهم إنِّي أعوذُ بك من المأثَمِ والمغرَم', search = '٢- اللهم إني أعوذ بك من عذاب القبر وأعوذ بك من فتنة المسيح الدجال وأعوذ بك من فتنة المحيا والممات اللهم إني أعوذ بك من المأثم والمغرم' WHERE id = 124;
UPDATE contents SET body = '٣- اللهم إني أعوذُ بك من شَرِّ ما عَمِلْتُ، ومن شر ما لم أعمل', search = '٣- اللهم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل' WHERE id = 125;
UPDATE contents SET body = '٤- اللهم إني أسألُكَ الجنَّةَ، وأعوذُ بك من النَّارِ', search = '٤- اللهم إني أسألك الجنة وأعوذ بك من النار' WHERE id = 126;
UPDATE contents SET body = '٥- اللهم إني ظلمتُ نفسي ظُلْمًا كثيرًا، ولا يغفرُ الذنوبَ إلَّا أنتَ، فاغفرْ لي مغفرةً مِن عِندِك، وارْحَمْني إنك أنتَ الغفورُ الرحيمُ', search = '٥- اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم' WHERE id = 127;
UPDATE contents SET body = '٦- اللهم حاسِبْني حسابًا يسيرًا', search = '٦- اللهم حاسبني حسابا يسيرا' WHERE id = 128;
UPDATE contents SET body = '٧- اللهم إني أسألُكَ يا اللهُ الواحدُ الأحدُ الصَّمَدُ، الذي لم يَلِدْ ولَمْ يُولَدْ، ولَمْ يَكُنْ له كُفُوًا أحدٌ، أن تَغْفِرَ لي ذُنُوبي، إنَّكَ أنتَ الغفورُ الرَّحيمُ', search = '٧- اللهم إني أسألك يا الله الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم' WHERE id = 129;
UPDATE contents SET body = '٨- اللهم إنِّي أسألُكَ بأنَّ لَكَ الحمدَ، لا إلهَ إلَّا أنتَ وحدَكَ، لا شريكَ لك، المنَّانُ، يا بديعَ السَّماواتِ والأرضِ، يا ذا الجلالِ والإكرامِ، يا حَيُّ يا قَيُّومُ، إنِّي أسألُكَ الجَنَّةَ، وأعوذُ بكَ من النَّارِ', search = '٨- اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار' WHERE id = 130;
UPDATE contents SET body = '٩- اللهم إنِّي أسألُكَ من الخيرِ كُلِّه، عاجِلِه وآجِلِه، ما عَلِمْتُ منه وما لم أعلمْ، وأعوذُ بك من الشَّرِّ كُلِّه، عاجِلِه وآجِلِه، ما عَلِمْتُ منه وما لَمْ أعلمْ، اللهم إنِّي أسألُكَ الجَنَّةَ، وما قَرَّبَ إليها مِنْ قَوْلٍ أو عَمَلٍ، وأعوذُ بكَ من النَّارِ، وما قَرَّبَ إليها من قولٍ أو عملٍ، اللهم إنِّي أسألُكَ من خيرِ ما سألَكَ عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأعوذُ بكَ من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأسألُكَ ما قَضَيْتَ لي مِنْ أمرٍ أن تجعلَ عاقِبَتَهُ لي رَشَدًا', search = '٩- اللهم إني أسألك من الخير كله عاجله وآجله ما علمت منه وما لم أعلم وأعوذ بك من الشر كله عاجله وآجله ما علمت منه وما لم أعلم اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل وأعوذ بك من النار وما قرب إليها من قول أو عمل اللهم إني أسألك من خير ما سألك عبدك ورسولك محمد صلى الله عليه وسلم وأعوذ بك من شر ما استعاذك منه عبدك ورسولك محمد صلى الله عليه وسلم وأسألك ما قضيت لي من أمر أن تجعل عاقبته لي رشدا' WHERE id = 131;
UPDATE contents SET body = '١٠- اللهم بِعِلْمِكَ الغيبَ، وقُدْرَتِكَ على الخَلْقِ، أَحْيِني ما علمتَ الحياةَ خيرًا لي، وتَوَفَّني إذا كانتِ الوفاةُ خيرًا لي، اللهم وأسألُكَ خشيتَكَ في الغيبِ والشهادةِ، وأسألُكَ كلمةَ الحقِّ والعدلِ في الغضبِ والرِّضَى، وأسألُكَ القصدَ في الفقرِ والغِنَى، وأسألُكَ نعيمًا لا يَبِيدُ، وأسألُكَ قُرَّةَ عينٍ لا تنفدُ، ولا تنقطعُ، وأسألُكَ الرِّضا بعد القضاءِ، وأسألُكَ بَرْدَ العيشِ بعد الموتِ، وأسألُكَ لَذَّةَ النَّظَرِ إلى وَجْهِكَ، وأسألُكَ الشوقَ إلى لقائِكَ، في غيرِ ضَرَّاءَ مُضِرَّةٍ، ولا فِتْنَةٍ مُضِلَّةٍ، اللهم زَيِّنَّا بزينةِ الإيمانِ، واجعلنا هُداةً مهتدين', search = '١٠- اللهم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي اللهم وأسألك خشيتك في الغيب والشهادة وأسألك كلمة الحق والعدل في الغضب والرضى وأسألك القصد في الفقر والغنى وأسألك نعيما لا يبيد وأسألك قرة عين لا تنفد ولا تنقطع وأسألك الرضا بعد القضاء وأسألك برد العيش بعد الموت وأسألك لذة النظر إلى وجهك وأسألك الشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة اللهم زينا بزينة الإيمان واجعلنا هداة مهتدين' WHERE id = 132;
UPDATE contents SET body = '١١- أحسنُ الكلامِ كلامُ اللهِ، وأحسنُ الهَدْيِ هَدْيُ محمدٍ صلى الله عليه وسلم', search = '١١- أحسن الكلام كلام الله وأحسن الهدي هدي محمد صلى الله عليه وسلم' WHERE id = 945;
UPDATE contents SET body = '١٢- اللهم اغفرْ لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ، وما أعلنتُ، وما أسرفتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، لا إله إلا أنت', search = '١٢- اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت' WHERE id = 133;
-- title 16
UPDATE contents SET body = '١- يُكَبِّرُ اللهَ عزَّ وجلَّ', search = '١- يكبر الله عز وجل' WHERE id = 946;
UPDATE contents SET body = '٢- لا إلهَ إلا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، وهو على كلِّ شيءٍ قديرٌ، لا حولَ ولا قوةَ إلا باللهِ، لا إلهَ إلا اللهُ، ولا نعبدُ إلا إيَّاهُ، له النعمةُ، وله الفضلُ، وله الثناءُ الحسنُ، لا إلهَ إلا اللهُ، مخلصينَ له الدينَ ولو كَرِهَ الكافرون', search = '٢- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير لا حول ولا قوة إلا بالله لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن لا إله إلا الله مخلصين له الدين ولو كره الكافرون' WHERE id = 134;
UPDATE contents SET body = '٣- أستغفرُ اللهَ، أستغفرُ اللهَ، اللهمَّ أنتَ السلامُ، ومنكَ السلامُ، تباركتَ يا ذا الجلالِ والإكرامِ', search = '٣- أستغفر الله أستغفر الله اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام' WHERE id = 135;
UPDATE contents SET body = '٤- لا إلهَ إلا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، وهو على كلِّ شيءٍ قديرٌ، اللهمَّ لا مانعَ لما أعطيتَ، ولا مُعطيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منكَ الجَدُّ', search = '٤- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد' WHERE id = 136;
UPDATE contents SET body = '٥- ويقرأ آية الكُرْسِيّ:
QuranText[(2:255:255)]', search = '٥- ويقرأ آية الكرسي 2255255' WHERE id = 137;
UPDATE contents SET body = '٦- ويقرأ السُّوَرَ المعوِّذاتِ: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، و﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، و﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾.', search = '٦- ويقرأ السور المعوذات ﴿ قلۡ هو ٱلله أحد ﴾ و﴿ قلۡ أعوذ برب ٱلۡفلق ﴾ و﴿ قلۡ أعوذ برب ٱلناس ﴾' WHERE id = 138;
UPDATE contents SET body = '٧- اللهمَّ أعِنِّي على ذِكرِكَ، وشُكرِكَ، وحُسنِ عبادتِكَ', search = '٧- اللهم أعني على ذكرك وشكرك وحسن عبادتك' WHERE id = 139;
UPDATE contents SET body = '٨- رَبِّ قِنِي عذابَكَ يومَ تجمعُ -أو: تبعثُ- عبادَكَ', search = '٨- رب قني عذابك يوم تجمع -أو تبعث- عبادك' WHERE id = 140;
UPDATE contents SET body = '٩- اللهمَّ إني أعوذُ بكَ من الكفرِ والفقرِ وعذابِ القبرِ', search = '٩- اللهم إني أعوذ بك من الكفر والفقر وعذاب القبر' WHERE id = 141;
UPDATE contents SET body = '١٠- اللهمَّ لا تُخزِني يومَ القيامةِ', search = '١٠- اللهم لا تخزني يوم القيامة' WHERE id = 1250;
UPDATE contents SET body = '١١- اللهمَّ إني أعوذُ بكَ من الجُبنِ، وأعوذُ بكَ أن أُرَدَّ إلى أرذلِ العمرِ، وأعوذُ بكَ من فتنةِ الدنيا، وأعوذُ بكَ من عذابِ القبرِ', search = '١١- اللهم إني أعوذ بك من الجبن وأعوذ بك أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وأعوذ بك من عذاب القبر' WHERE id = 143;
UPDATE contents SET body = '١٢- اللهمَّ إني أسألُكَ فعلَ الخيراتِ، وتَرْكَ المنكراتِ، وحبَّ المساكينِ، وأن تغفرَ لي وترحمَني، وتتوبَ عليَّ، وإذا أردتَ بعبادِكَ فتنةً فاقبضْني إليكَ غيرَ مفتونٍ', search = '١٢- اللهم إني أسألك فعل الخيرات وترك المنكرات وحب المساكين وأن تغفر لي وترحمني وتتوب علي وإذا أردت بعبادك فتنة فاقبضني إليك غير مفتون' WHERE id = 144;
