UPDATE contents SET body = 'لا إلهَ إلا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، يُحيي ويُميتُ، وهو على كلِّ شيءٍ قديرٌ [عشر مرَّات]', search = 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير عشر مرات' WHERE id = 149;
UPDATE contents SET body = 'لا إلهَ إلا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، يُحيي ويُميتُ، وهو على كلِّ شيءٍ قديرٌ [عشر مرَّات]', search = 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير عشر مرات' WHERE id = 962;
