UPDATE contents SET body = '١- باسمِكَ اللهمَّ أَحيا وأموتُ', search = '١- باسمك اللهم أحيا وأموت' WHERE id = 157;
UPDATE contents SET body = '٢- (يجمع كَفَّيْهِ، ثم يَنْفُثُ فيهما، ثم يقرأُ فيهما: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، والمعوِّذتين، ثم يمسح بهما ما استطاع من جسده، يبدأ بهما على رأسِه ووجهِه، وما أقبلَ مِن جَسَدِهِ)، يفعلُ ذلك كُلَّه ثلاثَ مرَّاتٍ.', search = '٢- يجمع كفيه ثم ينفث فيهما ثم يقرأ فيهما ﴿ قلۡ هو ٱلله أحد ﴾ والمعوذتين ثم يمسح بهما ما استطاع من جسده يبدأ بهما على رأسه ووجهه وما أقبل من جسده يفعل ذلك كله ثلاث مرات' WHERE id = 158;
UPDATE contents SET body = '٣- يضع يدَه اليمنى تحت خَدِّه، ثم يقول:', search = '٣- يضع يده اليمنى تحت خده ثم يقول' WHERE id = 1641;
UPDATE contents SET body = 'اللهمَّ قِنِي عذابَكَ يومَ تَبعثُ عبادَكَ [ثلاث مرَّات]', search = 'اللهم قني عذابك يوم تبعث عبادك ثلاث مرات' WHERE id = 159;
UPDATE contents SET body = '٤- باسمِكَ ربِّي وضعتُ جَنْبي، وبكَ أرفعُه، إن أمسكتَ نفسي فارحمْها، وإن أرسلتَها فاحفظْها بما تحفظُ به عبادَكَ الصالحين', search = '٤- باسمك ربي وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين' WHERE id = 160;
UPDATE contents SET body = '٥- الحمدُ للهِ الذي أطعمَنا، وسقانا، وكفانا، وآوانا، فكَمْ مِمَّن لا كافيَ له ولا مُؤْوِي', search = '٥- الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا فكم ممن لا كافي له ولا مؤوي' WHERE id = 161;
UPDATE contents SET body = '٦- ويقرأ آيةَ الكُرْسِيِّ:
QuranText[(2:255:255)]', search = '٦- ويقرأ آية الكرسي 2255255' WHERE id = 162;
UPDATE contents SET body = '٧- لا إلهَ إلا اللهُ وحدَه، لا شريكَ له، له المُلْكُ، وله الحمدُ، وهو على كلِّ شيءٍ قديرٌ، ولا حولَ ولا قوةَ إلا باللهِ، سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ', search = '٧- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير ولا حول ولا قوة إلا بالله سبحان الله والحمد لله ولا إله إلا الله والله أكبر' WHERE id = 163;
UPDATE contents SET body = '٨- اللهمَّ أنتَ خلقتَ نفسي، وأنتَ توفاها، لكَ مماتُها ومحياها، إن أحييتَها فاحفظْها، وإن أمتَّها فاغفرْ لها، اللهمَّ إني أسألُكَ العافية', search = '٨- اللهم أنت خلقت نفسي وأنت توفاها لك مماتها ومحياها إن أحييتها فاحفظها وإن أمتها فاغفر لها اللهم إني أسألك العافية' WHERE id = 164;
UPDATE contents SET body = '٩- أعوذُ بكلماتِ اللهِ التامَّاتِ من شرِّ ما خَلَقَ', search = '٩- أعوذ بكلمات الله التامات من شر ما خلق' WHERE id = 165;
UPDATE contents SET body = '١٠- اللهمَّ فاطرَ السماواتِ والأرضِ، عالمَ الغيبِ والشهادةِ، لا إلهَ إلا أنتَ، ربَّ كلِّ شيءٍ ومليكَهُ، أعوذُ بكَ من شرِّ نفسي، ومن شرِّ الشيطانِ وشِركِهِ، وأن أقترفَ على نفسي سوءًا، أو أجرَّه إلى مسلمٍ', search = '١٠- اللهم فاطر السماوات والأرض عالم الغيب والشهادة لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي ومن شر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم' WHERE id = 166;
UPDATE contents SET body = '١١- اللهمَّ ربَّ السماواتِ، وربَّ الأرضِ، وربَّ العرشِ العظيمِ، ربَّنا وربَّ كلِّ شيءٍ، فالِقَ الحَبِّ والنَّوى، مُنزِلَ التوراةِ والإنجيلِ والفُرْقانِ، أعوذُ بكَ من شرِّ كلِّ ذي شرٍّ أنتَ آخِذٌ بناصيتِه، أنتَ الأولُ فليس قبلَكَ شيءٌ، وأنتَ الآخِرُ فليس بعدَكَ شيءٌ، وأنتَ الظاهرُ فليس فوقَكَ شيءٌ، وأنتَ الباطنُ فليس دونَكَ شيءٌ، اقضِ عنَّا الدَّينَ، وأغنِنا من الفقرِ', search = '١١- اللهم رب السماوات ورب الأرض ورب العرش العظيم ربنا ورب كل شيء فالق الحب والنوى منزل التوراة والإنجيل والفرقان أعوذ بك من شر كل ذي شر أنت آخذ بناصيته أنت الأول فليس قبلك شيء وأنت الآخر فليس بعدك شيء وأنت الظاهر فليس فوقك شيء وأنت الباطن فليس دونك شيء اقض عنا الدين وأغننا من الفقر' WHERE id = 167;
UPDATE contents SET body = '١٢- اللهمَّ إني أعوذُ بوجهِكَ الكريمِ وكلِماتِكَ التامَّةِ من شرِّ ما أنتَ آخِذٌ بناصيتِه، اللهمَّ أنتَ تَكشِفُ المَغرَمَ والمأثَمَ، اللهمَّ لا يُهزَمُ جُندُكَ، ولا يُخلَفُ وعدُكَ، ولا ينفعُ ذا الجَدِّ منكَ الجَدُّ، سبحانَكَ اللهمَّ وبحمدِكَ', search = '١٢- اللهم إني أعوذ بوجهك الكريم وكلماتك التامة من شر ما أنت آخذ بناصيته اللهم أنت تكشف المغرم والمأثم اللهم لا يهزم جندك ولا يخلف وعدك ولا ينفع ذا الجد منك الجد سبحانك اللهم وبحمدك' WHERE id = 168;
UPDATE contents SET body = '١٣- باسمِ اللهِ وضعتُ جَنْبي، اللهمَّ اغفرْ لي ذَنبي، وأَخسِئْ شيطاني، وفُكَّ رِهاني، وثَقِّلْ ميزاني، واجعلْني في النَّدِيِّ الأعلى', search = '١٣- باسم الله وضعت جنبي اللهم اغفر لي ذنبي وأخسئ شيطاني وفك رهاني وثقل ميزاني واجعلني في الندي الأعلى' WHERE id = 169;
UPDATE contents SET body = '١٤- الحمدُ للهِ الذي كفاني وآواني، وأطعَمَني وأسقاني، والذي مَنَّ عليَّ فأفضلَ، والذي أعطاني فأجزلَ، الحمدُ للهِ على كلِّ حالٍ، اللهمَّ ربَّ كلِّ شيءٍ ومليكَهُ، وإلهَ كلِّ شيءٍ، أعوذُ بكَ من النار', search = '١٤- الحمد لله الذي كفاني وآواني وأطعمني وأسقاني والذي من علي فأفضل والذي أعطاني فأجزل الحمد لله على كل حال اللهم رب كل شيء ومليكه وإله كل شيء أعوذ بك من النار' WHERE id = 170;
