UPDATE contents SET body = '١- لا إلهَ إلا اللهُ العظيمُ الحليمُ، لا إلهَ إلا اللهُ ربُّ العرشِ العظيمِ، لا إلهَ إلا اللهُ ربُّ السماواتِ والأرضِ، لا إلهَ إلا اللهُ ربُّ العرشِ الكريمِ', search = '١- لا إله إلا الله العظيم الحليم لا إله إلا الله رب العرش العظيم لا إله إلا الله رب السماوات والأرض لا إله إلا الله رب العرش الكريم' WHERE id = 218;
