UPDATE contents SET body = '٥- اللهمَّ اشفِ «فلانًا» [ثلاث مرَّاتٍ]', search = '٥- اللهم اشف «فلانا» ثلاث مرات' WHERE id = 265;
UPDATE contents SET body = '٦- امسَحِ الباسَ، ربَّ الناسِ، بيدِكَ الشِّفاءُ، لا كاشِفَ له إلا أنتَ', search = '٦- امسح الباس رب الناس بيدك الشفاء لا كاشف له إلا أنت' WHERE id = 266;
UPDATE contents SET body = '٧- أسألُ اللهَ العظيمَ، ربَّ العرشِ العظيمِ أن يشفِيَكَ [سبع مرات]', search = '٧- أسأل الله العظيم رب العرش العظيم أن يشفيك سبع مرات' WHERE id = 977;
