UPDATE contents SET body = '١- باسمِ اللهِ، تُربَةُ أرضِنا، بِرِيقَةِ بعضِنا، يُشفى بهِ سَقيمُنا، بإذنِ ربِّنا', search = '١- باسم الله تربة أرضنا بريقة بعضنا يشفى به سقيمنا بإذن ربنا' WHERE id = 267;
UPDATE contents SET body = '٢- يقرأ بفاتحة الكتاب، ويجمع بُزَاقه، ويَتْفُل، ويُعَوِّذُ المريضَ، فيمسحُ بيده اليمنى، ويقول:', search = '٢- يقرأ بفاتحة الكتاب ويجمع بزاقه ويتفل ويعوذ المريض فيمسح بيده اليمنى ويقول' WHERE id = 268;
UPDATE contents SET body = '٣- اللهمَّ ربَّ الناسِ، أذهِبِ الباسَ، اشفِ أنتَ الشَّافي، لا شفاءَ إلا شفاؤُكَ، شفاءً لا يُغادِرُ سَقَمًا', search = '٣- اللهم رب الناس أذهب الباس اشف أنت الشافي لا شفاء إلا شفاؤك شفاء لا يغادر سقما' WHERE id = 269;
UPDATE contents SET body = '٤- باسمِ اللهِ أُرقيكَ، من كلِّ شيءٍ يُؤذيكَ، من شرِّ كلِّ نفسٍ أو عينِ حاسدٍ، اللهُ يشفِيكَ، باسمِ اللهِ أُرقيكَ', search = '٤- باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد الله يشفيك باسم الله أرقيك' WHERE id = 270;
UPDATE contents SET body = '٥- باسمِ اللهِ يُبريكَ، ومن كلِّ داءٍ يشفيكَ، ومن شرِّ حاسدٍ إذا حسَدَ، وشرِّ كلِّ ذي عَينٍ', search = '٥- باسم الله يبريك ومن كل داء يشفيك ومن شر حاسد إذا حسد وشر كل ذي عين' WHERE id = 978;
-- title 45
UPDATE contents SET body = '١- إنَّهُ قد حَضَرَ منِّي ما ليسَ اللهُ بتاركٍ مِنْهُ أحدًا لِمُوافاةِ يومِ القيامةِ', search = '١- إنه قد حضر مني ما ليس الله بتارك منه أحدا لموافاة يوم القيامة' WHERE id = 271;
UPDATE contents SET body = '٢- ما أرى الأجلَ إلا اقتربَ، فاتقوا اللهَ واصبروا', search = '٢- ما أرى الأجل إلا اقترب فاتقوا الله واصبروا' WHERE id = 272;
UPDATE contents SET body = '٣- ويقول لهم:', search = '٣- ويقول لهم' WHERE id = 1616;
UPDATE contents SET body = '١- لا إلهَ إلا اللهُ، إنَّ للموتِ سَكَراتٍ، اللهمَّ اغفرْ لي، وارحمني، وأَلْحِقْني بالرفيقِ الأعلى', search = '١- لا إله إلا الله إن للموت سكرات اللهم اغفر لي وارحمني وألحقني بالرفيق الأعلى' WHERE id = 275;
UPDATE contents SET body = '٢- ويَحْمَدُ اللهَ عزَّ وجلَّ', search = '٢- ويحمد الله عز وجل' WHERE id = 276;
UPDATE contents SET body = '٣- ويُكْثِرُ من قولِ: «لا إله إلَّا الله»؛ ليكونَ آخِرَ كلامِهِ، أو يُلَقِّنُهُ إيَّاها بِرِفْقٍ مَنْ حَضَرَهُ', search = '٣- ويكثر من قول «لا إله إلا الله» ليكون آخر كلامه أو يلقنه إياها برفق من حضره' WHERE id = 277;
UPDATE contents SET body = '١- إنّا للهِ، وإنّا إليهِ راجعونَ، اللهمَّ أَجِرْني في مصيبتي، وأَخلِفْ لي خيرًا منها', search = '١- إنا لله وإنا إليه راجعون اللهم أجرني في مصيبتي وأخلف لي خيرا منها' WHERE id = 982;
UPDATE contents SET body = '٢- إنَّ العينَ تدمعُ، والقلبَ يحزنُ، ولا نقولُ إلا ما يُرضي ربَّنا، وإنَّا بفراقِكَ يا «فلان» لمحزونون', search = '٢- إن العين تدمع والقلب يحزن ولا نقول إلا ما يرضي ربنا وإنا بفراقك يا «فلان» لمحزونون' WHERE id = 983;
-- title 46
UPDATE contents SET body = '١- اللهمَّ اغفرْ له، وارحمْهُ، وعافِهِ، واعفُ عنهُ، وأكرِمْ نُزُلَهُ، ووَسِّعْ مُدخلَهُ، واغسِلْهُ بالماءِ والثَّلجِ والبرَدِ، ونَقِّهِ من الخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ، وأَبدِلْهُ دارًا خيرًا من دارِهِ، وأهلًا خيرًا من أهلِهِ، وزوجًا خيرًا من زوجِهِ وأدخِلْهُ الجنةَ، وأعِذْهُ من عذابِ القبرِ، ومن عذابِ النارِ', search = '١- اللهم اغفر له وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس وأبدله دارا خيرا من داره وأهلا خيرا من أهله وزوجا خيرا من زوجه وأدخله الجنة وأعذه من عذاب القبر ومن عذاب النار' WHERE id = 278;
UPDATE contents SET body = '٢- اللهمَّ اغفرْ لحَيِّنا ومَيِّتِنا، وشاهدِنا وغائبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنا وأُنثانا، اللهمَّ من أحييتَهُ منَّا فأحيِهِ على الإسلامِ، ومن توفَّيتَهُ منَّا فتوفَّهُ على الإيمانِ، اللهمَّ لا تحرِمْنا أجرَهُ، ولا تُضِلَّنا بعدَهُ', search = '٢- اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا اللهم من أحييته منا فأحيه على الإسلام ومن توفيته منا فتوفه على الإيمان اللهم لا تحرمنا أجره ولا تضلنا بعده' WHERE id = 279;
UPDATE contents SET body = '٣- اللهمَّ أنتَ ربُّها، وأنتَ خلقتَها، وأنتَ هديتَها للإسلامِ، وأنتَ قبضتَ روحَها، وأنتَ أعلمُ بسرِّها وعلانيتِها، جئنا شُفَعاءَ، فاغفرْ لها', search = '٣- اللهم أنت ربها وأنت خلقتها وأنت هديتها للإسلام وأنت قبضت روحها وأنت أعلم بسرها وعلانيتها جئنا شفعاء فاغفر لها' WHERE id = 280;
UPDATE contents SET body = '٤- اللهمَّ إنَّ فلانَ بنَ فلانٍ في ذِمَّتِكَ وحَبلِ جِوارِكَ، فَقِهِ فتنةَ القبرِ وعذابَ النارِ، وأنتَ أهلُ الوَفاءِ والحقِّ، فاغفرْ له، وارحمْهُ، إنَّكَ أنتَ الغفورُ الرحيمُ', search = '٤- اللهم إن فلان بن فلان في ذمتك وحبل جوارك فقه فتنة القبر وعذاب النار وأنت أهل الوفاء والحق فاغفر له وارحمه إنك أنت الغفور الرحيم' WHERE id = 281;
UPDATE contents SET body = '٥- اللهمَّ عبدُكَ وابنُ أمتِكَ، احتاجَ إلى رحمتِكَ، وأنتَ غنيٌّ عن عذابِهِ، إن كانَ محسنًا؛ فزِدْ في حسناتِهِ، وإن كانَ مسيئًا؛ فتجاوَزْ عنهُ', search = '٥- اللهم عبدك وابن أمتك احتاج إلى رحمتك وأنت غني عن عذابه إن كان محسنا فزد في حسناته وإن كان مسيئا فتجاوز عنه' WHERE id = 282;
UPDATE contents SET body = '٦- وكان أبو هريرةَ رضي الله عنه يدعو في صلاة الجنازة:', search = '٦- وكان أبو هريرة رضي الله عنه يدعو في صلاة الجنازة' WHERE id = 1634;
UPDATE contents SET body = '١- اللهمَّ اجعلْهُ لنا سَلَفًا وفَرَطًا وأجرًا', search = '١- اللهم اجعله لنا سلفا وفرطا وأجرا' WHERE id = 985;
UPDATE contents SET body = '٢- اللهمَّ أَعِذْهُ من عذابِ القبرِ', search = '٢- اللهم أعذه من عذاب القبر' WHERE id = 986;
UPDATE contents SET body = '١- السلامُ عليكم دارَ قومٍ مؤمنين، وأتاكم ما تُوعَدون، وإنَّا إن شاءَ اللهُ بكم لاحِقونَ، اللهمَّ اغفرْ لأهلِ «هذه المقابرِ»', search = '١- السلام عليكم دار قوم مؤمنين وأتاكم ما توعدون وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل «هذه المقابر»' WHERE id = 287;
UPDATE contents SET body = '٢- أو: السلامُ عليكم أهلَ دارِ قومٍ مؤمنين، وإنَّا وإيَّاكُم، وما تُوعَدونَ غدًا مُؤجَّلون، وإنَّا إن شاءَ اللهُ بكم لاحِقون، اللهمَّ اغفرْ لأهلِ «هذه المقابرِ»', search = '٢- أو السلام عليكم أهل دار قوم مؤمنين وإنا وإياكم وما توعدون غدا مؤجلون وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل «هذه المقابر»' WHERE id = 288;
UPDATE contents SET body = '٣- أو: السلامُ على أهلِ الدِّيارِ من المؤمنين والمسلمين، ويرحمُ اللهُ المُستَقدِمينَ منكم ومِنَّا والمُستأخِرين، وإنَّا إن شاءَ اللهُ بكم لاحِقون', search = '٣- أو السلام على أهل الديار من المؤمنين والمسلمين ويرحم الله المستقدمين منكم ومنا والمستأخرين وإنا إن شاء الله بكم لاحقون' WHERE id = 289;
UPDATE contents SET body = '٤- أو: السلامُ عليكم أهلَ الديارِ من المؤمنين والمسلمين، وإنَّا إن شاءَ اللهُ بكم لَلاحِقونَ، أنتم لنا فَرَطٌ، ونحن لكم تَبَعٌ، أسألُ اللهَ لنا ولكُم العافيةَ', search = '٤- أو السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم للاحقون أنتم لنا فرط ونحن لكم تبع أسأل الله لنا ولكم العافية' WHERE id = 290;
-- title 48
UPDATE contents SET body = 'إنِّي صائمٌ، إنِّي صائمٌ [مرتين أو أكثر]', search = 'إني صائم إني صائم مرتين أو أكثر', source = 'ما يقول إذا رأى الهلال. (ص176)

حاشية: والأظهر أنه يُسْمِعه ذلك لينزجِر.' WHERE id = 295;
