UPDATE contents SET body = '١- أستودِعُ اللهَ دِينَكَ، وأمانَتَكَ، وخَوَاتِيمَ عَمَلِكَ', search = '١- أستودع الله دينك وأمانتك وخواتيم عملك' WHERE id = 299;
UPDATE contents SET body = '٢- زَوَّدَكَ اللهُ التقوى، وغفر ذَنْبَكَ، ويَسَّرَ لَكَ الخيرَ حيثما كُنتَ', search = '٢- زودك الله التقوى وغفر ذنبك ويسر لك الخير حيثما كنت' WHERE id = 300;
UPDATE contents SET body = '٣- عليكَ بتقوى اللهِ، والتكبيرِ على كلِّ شَرَفٍ', search = '٣- عليك بتقوى الله والتكبير على كل شرف' WHERE id = 301;
UPDATE contents SET body = '١- الحمدُ للهِ
﴿ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ﴾
الحمدُ للهِ، الحمدُ للهِ، الحمدُ للهِ، اللهُ أكبرُ، اللهُ أكبرُ، اللهُ أكبرُ، سبحانَكَ إنِّي ظلمتُ نفسي، فاغفِرْ لي، إنه لا يغفرُ الذنوبَ إلا أنتَ', search = '١- الحمد لله ﴿ سبۡحن ٱلذي سخر لنا هذا وما كنا لهۥ مقۡرنين ١٣ وإنآ إلى ربنا لمنقلبون ﴾ الحمد لله الحمد لله الحمد لله الله أكبر الله أكبر الله أكبر سبحانك إني ظلمت نفسي فاغفر لي إنه لا يغفر الذنوب إلا أنت' WHERE id = 306;
UPDATE contents SET body = '٢- اللهم إنَّا نسألُكَ في سَفَرِنَا هذا البِرَّ والتقوى، ومن العمل ما تَرْضَى، اللهم هَوِّنْ علينا سَفَرَنَا هذا، واطْوِ عَنَّا بُعْدَه، اللهُمَّ أنتَ الصَّاحِبُ في السَّفَرِ، والخَلِيفَةُ في الأهل', search = '٢- اللهم إنا نسألك في سفرنا هذا البر والتقوى ومن العمل ما ترضى اللهم هون علينا سفرنا هذا واطو عنا بعده اللهم أنت الصاحب في السفر والخليفة في الأهل' WHERE id = 307;
UPDATE contents SET body = '٣- اللهم اصْحَبْنَا بِنُصْحِكَ، وَاقْلِبْنَا بِذِمَّةٍ، اللهم ازْوِ لنا الأرضَ، وهَوِّنْ علينا السَّفَرَ', search = '٣- اللهم اصحبنا بنصحك واقلبنا بذمة اللهم ازو لنا الأرض وهون علينا السفر' WHERE id = 882;
UPDATE contents SET body = '٤- اللهم إني أعوذُ بِكَ مِنْ وَعْثاءِ السفر، وكَآبَةِ المنظر، وسُوءِ المُنقَلَبِ في المالِ والأهل', search = '٤- اللهم إني أعوذ بك من وعثاء السفر وكآبة المنظر وسوء المنقلب في المال والأهل' WHERE id = 308;
UPDATE contents SET body = '٥- اللهم إني أعوذُ بِكَ من الحَوْرِ بعدَ الكَوْنِ، ومن دعوةِ المظلوم، ومن سُوءِ المنظرِ في الأهلِ والمال', search = '٥- اللهم إني أعوذ بك من الحور بعد الكون ومن دعوة المظلوم ومن سوء المنظر في الأهل والمال' WHERE id = 309;
UPDATE contents SET body = '١- اللهُ أكبرُ، اللهُ أكبرُ، اللهُ أكبرُ', search = '١- الله أكبر الله أكبر الله أكبر' WHERE id = 871;
UPDATE contents SET body = '٢- سبحانَ الذي سَخَّرَ لنا هذا، وما كُنَّا له مُقْرِنين، وإنَّا إلى رَبِّنا لَمُنقَلِبون، اللهمَّ إنَّا نسألُكَ في سفرِنا هذا البِرَّ والتقوى، ومن العَمَلِ ما ترضى، اللهمَّ هَوِّنْ علينا سَفَرَنا هذا، واطْوِ عنَّا بُعْدَه، اللهم أنتَ الصاحِبُ في السَّفَرِ، والخليفةُ في الأهل، اللهم إنِّي أعوذُ بكَ من وَعْثاءِ السفر، وكآبَةِ المنظر، وسُوءِ المُنقَلَبِ في المالِ والأهل', search = '٢- سبحان الذي سخر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون اللهم إنا نسألك في سفرنا هذا البر والتقوى ومن العمل ما ترضى اللهم هون علينا سفرنا هذا واطو عنا بعده اللهم أنت الصاحب في السفر والخليفة في الأهل اللهم إني أعوذ بك من وعثاء السفر وكآبة المنظر وسوء المنقلب في المال والأهل' WHERE id = 872;
UPDATE contents SET body = '٣- آيِبُونَ، تائِبُونَ، عابِدُونَ، لِرَبِّنا حامِدُونَ', search = '٣- آيبون تائبون عابدون لربنا حامدون' WHERE id = 873;
