UPDATE contents SET body = '١- السلامُ عليكم دارَ قومٍ مؤمنين، وَأَتَاكُمْ ما تُوعَدُونَ، وإنَّا إن شاءَ اللهُ بكُمْ لاحِقونَ؛ اللَّهُمَّ اغْفِرْ لأهل بقيعِ الغَرْقَدِ', search = '١- السلام عليكم دار قوم مؤمنين وأتاكم ما توعدون وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل بقيع الغرقد' WHERE id = 348;
UPDATE contents SET body = '٢- أو: السلامُ عليكم أهلَ دارِ قومٍ مؤمنين، وإنَّا وإيَّاكم، وما تُوعَدون غدًا مُؤَجَّلون، وإنَّا إن شاء اللهُ بكم لاحقون، اللهم اغْفِرْ لأهلِ البقيعِ', search = '٢- أو السلام عليكم أهل دار قوم مؤمنين وإنا وإياكم وما توعدون غدا مؤجلون وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل البقيع' WHERE id = 349;
UPDATE contents SET body = '٣- أو: السَّلامُ على أهلِ الديارِ من المؤمنين والمسلمين، ويَرْحَمُ اللهُ المستقدمينَ منكم ومنَّا والمُستأخِرين، وإنَّا إنْ شاء اللهُ بِكُمْ لاحقونَ', search = '٣- أو السلام على أهل الديار من المؤمنين والمسلمين ويرحم الله المستقدمين منكم ومنا والمستأخرين وإنا إن شاء الله بكم لاحقون' WHERE id = 350;
UPDATE contents SET body = '٤- أو: السلامُ عليكم أهلَ الدِّيارِ من المؤمنين والمسلمين، وإنَّا إن شاء اللهُ بكم لَلَاحِقون، أنتم لنا فَرَطٌ، ونحن لكم تَبَعٌ، أسأل اللهَ لنا ولكم العافيةَ', search = '٤- أو السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم للاحقون أنتم لنا فرط ونحن لكم تبع أسأل الله لنا ولكم العافية' WHERE id = 351;
