UPDATE contents SET body = '١- ﴿ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', search = '١- ﴿ ربنآ أفۡرغۡ عليۡنا صبۡرا وثبتۡ أقۡدامنا وٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾' WHERE id = 355;
UPDATE contents SET body = '٢- ﴿ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', search = '٢- ﴿ ربنا ٱغۡفرۡ لنا ذنوبنا وإسۡرافنا في أمۡرنا وثبتۡ أقۡدامنا وٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾' WHERE id = 356;
UPDATE contents SET body = '٣- ويُكَبِّرُ اللهَ عَزَّ وَجَلَّ، ولا يرفع صوته.', search = '٣- ويكبر الله عز وجل ولا يرفع صوته' WHERE id = 357;
UPDATE contents SET body = '٤- لا إله إلا الله وحده، أَعَزَّ جُنْدَه، ونَصَرَ عبدَه، وغَلَبَ الأحزابَ وحدَه، فلا شيءَ بعدَه', search = '٤- لا إله إلا الله وحده أعز جنده ونصر عبده وغلب الأحزاب وحده فلا شيء بعده' WHERE id = 358;
