UPDATE contents SET body = '١- لا إله إلا الله.', search = '١- لا إله إلا الله' WHERE id = 480;
UPDATE contents SET body = '٢- أشهدُ ألَّا إله إلا الله وحدَه، لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه، وأنَّ عيسى عبدُ اللهِ ورسُولُه، وكلمتُهُ ألقاها إلى مريمَ ورُوحٌ منه، وأنَّ الجنَّةَ حَقٌّ، والنَّارَ حَقٌّ.', search = '٢- أشهد ألا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله وأن عيسى عبد الله ورسوله وكلمته ألقاها إلى مريم وروح منه وأن الجنة حق والنار حق' WHERE id = 481;
UPDATE contents SET body = '٣- لا إله إلا الله وحدَه، لا شريكَ له، اللهُ أكبرُ كبيرًا، والحمدُ لله كثيرًا، سبحانَ اللهِ رَبِّ العالمين، لا حولَ ولا قوَّةَ إلا بالله العزيزِ الحكيمِ، اللهم اغفِرْ لِي، وارحمني، واهدِني، وارزقني.', search = '٣- لا إله إلا الله وحده لا شريك له الله أكبر كبيرا والحمد لله كثيرا سبحان الله رب العالمين لا حول ولا قوة إلا بالله العزيز الحكيم اللهم اغفر لي وارحمني واهدني وارزقني' WHERE id = 482;
UPDATE contents SET body = '٤- اللهم إني أُشْهِدُكَ، وأُشْهِدُ ملائكتَك، وحَمَلَةَ عرشِكَ، وأُشْهِدُ مَن في السماواتِ ومَن في الأرض أنَّك أنتَ اللهُ، لا إله إلا أنتَ وحدَك، لا شريكَ لك، وأشهدُ أنَّ محمدًا عبدُكَ ورسولُك. [ثلاث مرات]', search = '٤- اللهم إني أشهدك وأشهد ملائكتك وحملة عرشك وأشهد من في السماوات ومن في الأرض أنك أنت الله لا إله إلا أنت وحدك لا شريك لك وأشهد أن محمدا عبدك ورسولك ثلاث مرات', source = 'من صيغ التهليل. (ص285)' WHERE id = 483;
UPDATE contents SET body = '٥- لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كلِّ شيءٍ قدير. [عشر مرات، أو مئة مرة، أو أكثر]', search = '٥- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير عشر مرات أو مئة مرة أو أكثر', source = 'من صيغ التهليل. (ص286)' WHERE id = 484;
