UPDATE contents SET body = '١- أستغفِرُ الله، وأتوبُ إليه. [كثيرًا]', search = '١- أستغفر الله وأتوب إليه كثيرا', source = 'من صيغ الاستغفار في السنة الشريفة. (ص306)' WHERE id = 1738;
UPDATE contents SET body = '٢- ربِّ اغفِرْ لي، وتُبْ عَلَيَّ، إنَّك أنتَ التواب الرحيم. [مئة مرة]', search = '٢- رب اغفر لي وتب علي إنك أنت التواب الرحيم مئة مرة', source = 'من صيغ الاستغفار في السنة الشريفة. (ص306)' WHERE id = 1739;
UPDATE contents SET body = '٣- سبحان الله وبحمده، أستغفِرُ الله وأتوبُ إليه.', search = '٣- سبحان الله وبحمده أستغفر الله وأتوب إليه' WHERE id = 1740;
UPDATE contents SET body = '٤- يا ربِّ، أنتَ أنتَ، وأنا أنا، أنتَ العوَّادُ بالمغفرة، وأنا العوَّادُ بالذنوب.', search = '٤- يا رب أنت أنت وأنا أنا أنت العواد بالمغفرة وأنا العواد بالذنوب' WHERE id = 1741;
UPDATE contents SET body = '٥- اللهم اغفِر لي، وارحمني، وارزقني، واهدني، وعافني.', search = '٥- اللهم اغفر لي وارحمني وارزقني واهدني وعافني' WHERE id = 1742;
UPDATE contents SET body = '٦- أستغفِرُ الله الذي لا إله إلا هو الحيُّ القيُّومُ، وأتوبُ إليه.', search = '٦- أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه' WHERE id = 1743;
UPDATE contents SET body = '٧- اللهم اغفِرْ لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به مني، إنَّك أنت المُقدِّمُ والمؤخِّرُ، لا إله إلا أنتَ.', search = '٧- اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني إنك أنت المقدم والمؤخر لا إله إلا أنت' WHERE id = 1744;
UPDATE contents SET body = '٨- لا إله إلا أنت، إني قد ظلمتُ نفسي، فاغفِرْ لي ذنوبي، إنه لا يغفِرُ الذنوبَ إلا أنتَ.', search = '٨- لا إله إلا أنت إني قد ظلمت نفسي فاغفر لي ذنوبي إنه لا يغفر الذنوب إلا أنت' WHERE id = 1745;
UPDATE contents SET body = '٩- اللهُمَّ أنتَ رَبِّي، لا إله إلا أنتَ، خَلَقْتَني وأنا عبدُكَ، وأنا على عهدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بِكَ مِنْ شَرِّ ما صَنعتُ، أَبُوءُ لَكَ بِنعمَتِكَ عَلَيَّ، وأبوءُ بِذَنبي، فاغفِر لي، فإنه لا يغفرُ الذُّنوبَ إلَّا أنتَ.', search = '٩- اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت' WHERE id = 1746;
UPDATE contents SET body = '١٠- اللهم اغفِرْ لي خطيئتي وجهلي، وإسرافي في أمري، وما أنتَ أعلمُ به منِّي، اللهم اغفِرْ لي جِدِّي وهَزْلي، وخطئي وعَمْدِي، وكلُّ ذلك عندي، اللهم اغفِر لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ وأنتَ المؤخِّرُ، وأنتَ على كُلِّ شيءٍ قدير.', search = '١٠- اللهم اغفر لي خطيئتي وجهلي وإسرافي في أمري وما أنت أعلم به مني اللهم اغفر لي جدي وهزلي وخطئي وعمدي وكل ذلك عندي اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر وأنت على كل شيء قدير' WHERE id = 1747;
UPDATE contents SET body = '١١- اللهم أنتَ ربي، وأنا عبدُكَ، ظلمتُ نفسي، واعترفتُ بذنبي يا رَبِّ، فاغفِرْ لي ذنبي، إنَّكَ أنتَ ربي، إنه لا يغفِرُ الذنبَ إلا أنتَ.', search = '١١- اللهم أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي يا رب فاغفر لي ذنبي إنك أنت ربي إنه لا يغفر الذنب إلا أنت' WHERE id = 1748;
UPDATE contents SET body = '١٢- ومن أسباب مغفرة الذنوب: كثرة الصلاة على رسول الله ﷺ؛ لأنَّ أُبَيَّ بنَ كعبٍ رضي الله عنه لَمَّا قال للنبي ﷺ: «أجعلُ لكَ صلاتي كلَّها؟» قال له النبيُّ ﷺ: «إذَن تُكفَى همَّكَ، وَيُغْفَرُ لك ذنبُك».', search = '١٢- ومن أسباب مغفرة الذنوب كثرة الصلاة على رسول الله لأن أبي بن كعب رضي الله عنه لما قال للنبي «أجعل لك صلاتي كلها » قال له النبي «إذن تكفى همك ويغفر لك ذنبك»' WHERE id = 1749;
