UPDATE contents SET body = '٥- الحمدُ لله حمدًا كثيرًا طيِّبًا مباركًا فيه مُبَارَكًا عليه، كما يُحِبُّ رَبُّنا ويَرْضَى.', search = '٥- الحمد لله حمدا كثيرا طيبا مباركا فيه مباركا عليه كما يحب ربنا ويرضى' WHERE id = 1831;
UPDATE contents SET body = '٦- الله أكبرُ كبيرًا، والحمد لله كثيرًا، وسبحانَ الله بُكرةً وأصيلًا.', search = '٦- الله أكبر كبيرا والحمد لله كثيرا وسبحان الله بكرة وأصيلا' WHERE id = 1832;
UPDATE contents SET body = '٧- اللهم لك الحمدُ، أنتَ نورُ السماوات والأرض ومَنْ فيهنَّ، ولك الحمدُ، أنتَ قَيِّمُ السماواتِ والأرضِ ومَنْ فيهن، ولك الحمدُ، أنتَ مَلِكُ السماواتِ والأرضِ ومَن فيهن، ولك الحمدُ، أنت الحقُّ، ووعدُكَ حقٌّ، وقولُك حَقٌّ، ولقاؤك حقٌّ، والجنَّةُ حقٌّ، والنارُ حَقٌّ، والساعةُ حَقٌّ، والنبيون حَقٌّ، ومحمَّدٌ حَقٌّ.', search = '٧- اللهم لك الحمد أنت نور السماوات والأرض ومن فيهن ولك الحمد أنت قيم السماوات والأرض ومن فيهن ولك الحمد أنت ملك السماوات والأرض ومن فيهن ولك الحمد أنت الحق ووعدك حق وقولك حق ولقاؤك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق' WHERE id = 1833;
UPDATE contents SET body = '٨- اللهم ربنا لك الحمد مِلءَ السماواتِ ومِلْءَ الأرضِ ومِلءَ ما بينهما، ومِلْءَ ما شئتَ من شيء بعد، أهلَ الثناءِ والمجد، أَحَقُّ ما قال العبدُ، وكُلُّنا لك عبدٌ، اللهم لا مانِعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منك الجَدُّ.', search = '٨- اللهم ربنا لك الحمد ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد' WHERE id = 1834;
