UPDATE contents SET body = '٤- الله أكبر، الله أكبر، الله أكبر، ولله الحمد، الله أكبر وأجلُّ، الله أكبر على ما هدانا.', search = '٤- الله أكبر الله أكبر الله أكبر ولله الحمد الله أكبر وأجل الله أكبر على ما هدانا' WHERE id = 1863;
UPDATE contents SET body = '٥- الله أكبر، الله أكبر، الله أكبر، لا إله إلا الله، والله أكبر، الله أكبر، الله أكبر، ولله الحمد.', search = '٥- الله أكبر الله أكبر الله أكبر لا إله إلا الله والله أكبر الله أكبر الله أكبر ولله الحمد' WHERE id = 1864;
