UPDATE contents SET body = '٢٣- ﴿ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ﴾', search = '٢٣- ﴿ ربنا ءاتنا من لدنك رحۡمة وهيئۡ لنا منۡ أمۡرنا رشدا ﴾' WHERE id = 647;
UPDATE contents SET body = '٢٤- ﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ ﴾', search = '٢٤- ﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأدۡخلۡني برحۡمتك في عبادك ٱلصلحين ﴾' WHERE id = 686;
