UPDATE contents SET body = '٢٧- ﴿ رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴾', search = '٢٧- ﴿ رب ٱرۡحمۡهما كما ربياني صغيرا ﴾' WHERE id = 629;
UPDATE contents SET body = '٢٨- اللَّهُمَّ إنِّي أسألُكَ بأنَّ لَكَ الحمدَ، لا إلهَ إلَّا أنتَ وحدَكَ، لا شريكَ لكَ، المَنَّانُ، يا بديعَ السماواتِ والأرضِ، يا ذا الجلالِ والإكرامِ، يا حيُّ يا قيُّومُ، إنِّي أسألُكَ الجَنَّةَ، وأعوذُ بِكَ من النَّارِ.', search = '٢٨- اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار' WHERE id = 1993;
UPDATE contents SET body = '٢٩- لا إلهَ إلا اللهُ الحليمُ الكريمُ، لا إلهَ إلا اللهُ العليُّ العظيمُ، لا إله إلا اللهُ ربُّ السماواتِ السَّبعِ، وربُّ العرشِ الكريم.', search = '٢٩- لا إله إلا الله الحليم الكريم لا إله إلا الله العلي العظيم لا إله إلا الله رب السماوات السبع ورب العرش الكريم' WHERE id = 611;
UPDATE contents SET body = '٣٠- اللَّهُمَّ إني أسألُكَ العفوَ والعافيةَ في الدُّنيا والآخِرة.', search = '٣٠- اللهم إني أسألك العفو والعافية في الدنيا والآخرة' WHERE id = 657;
UPDATE contents SET body = '٣١- اللَّهُمَّ إني أسألُكَ من فضلِكَ ورحمتِكَ، فإنه لا يملكُها إلا أنتَ.', search = '٣١- اللهم إني أسألك من فضلك ورحمتك فإنه لا يملكها إلا أنت' WHERE id = 699;
UPDATE contents SET body = '٣٢- اللَّهُمَّ أنتَ رَبِّي، وأنا عبدُكَ، ظَلَمْتُ نفسي، واعترفتُ بذنبي يا ربِّ، فاغفِرْ لي ذنبي، إنكَ أنتَ ربي، إنه لا يغفرُ الذنبَ إلا أنتَ.', search = '٣٢- اللهم أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي يا رب فاغفر لي ذنبي إنك أنت ربي إنه لا يغفر الذنب إلا أنت' WHERE id = 751;
UPDATE contents SET body = '٣٣- ربِّ اغفِر لي خطيئتي يومَ الدين.', search = '٣٣- رب اغفر لي خطيئتي يوم الدين' WHERE id = 736;
UPDATE contents SET body = '٣٤- رَبِّ أَعِنِّي، ولا تُعِنْ عَلَيَّ، وانصُرْني، ولا تَنْصُرْ عَلَيَّ، وامْكُرْ لِي، ولا تَمْكُرْ عَلَيَّ، واهْدِنِي، وَيَسِّرِ الهُدَى لي، وانصرني على مَنْ بَغَى عَلَيَّ، رَبِّ اجعلني لك ذكَّارًا، لك شكَّارًا، لك رَهَّابًا، لَكَ مِطْواعًا، لكَ مُخْبِتًا، إليكَ أوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وثَبِّتْ حُجَّتِي، واهْدِ قَلْبِي، وسَدِّدْ لِساني، واسْلُلْ سَخِيمَةَ صدري.', search = '٣٤- رب أعني ولا تعن علي وانصرني ولا تنصر علي وامكر لي ولا تمكر علي واهدني ويسر الهدى لي وانصرني على من بغى علي رب اجعلني لك ذكارا لك شكارا لك رهابا لك مطواعا لك مخبتا إليك أواها منيبا رب تقبل توبتي واغسل حوبتي وأجب دعوتي وثبت حجتي واهد قلبي وسدد لساني واسلل سخيمة صدري' WHERE id = 769;
UPDATE contents SET body = '٣٥- اللهم إنِّي أعوذُ برضاكَ مِن سَخَطِكَ، وأعوذُ بمعافاتِكَ من عُقوبتِكَ، وأعوذُ بِكَ مِنْكَ، لا أُحْصِي ثناءً عليك، أنتَ كما أثنيتَ على نفْسِكَ.', search = '٣٥- اللهم إني أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك' WHERE id = 1994;
UPDATE contents SET body = '٣٦- اللهم إني أعوذُ بِكَ من زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عافيتِكَ، وفُجَاءَةِ نِقْمَتِكَ، وجميعِ سُخْطِكَ.', search = '٣٦- اللهم إني أعوذ بك من زوال نعمتك وتحول عافيتك وفجاءة نقمتك وجميع سخطك' WHERE id = 654;
UPDATE contents SET body = '٣٧- اللهم أصلِحْ لي دينيَ الذي هو عِصْمَةُ أمري، وأصلح لي دنيايَ التي فيها مَعاشي، وأصلِحْ لي آخِرَتي التي فيها مَعادي، واجعلِ الحياةَ زيادةً لي في كُلِّ خَيرٍ، واجعلِ الموتَ راحةً لي من كُلِّ شَرٍّ.', search = '٣٧- اللهم أصلح لي ديني الذي هو عصمة أمري وأصلح لي دنياي التي فيها معاشي وأصلح لي آخرتي التي فيها معادي واجعل الحياة زيادة لي في كل خير واجعل الموت راحة لي من كل شر' WHERE id = 653;
UPDATE contents SET body = '٣٨- اللهُمَّ أَعِنَّا على شُكْرِكَ، وذِكْرِكَ، وحُسْنِ عبادتِك.', search = '٣٨- اللهم أعنا على شكرك وذكرك وحسن عبادتك' WHERE id = 715;
UPDATE contents SET body = '٣٩- اللهم إني أعوذ بك أن أُشْرِكَ بك وأنا أعلم، وأستغفرك لما لا أعلم.', search = '٣٩- اللهم إني أعوذ بك أن أشرك بك وأنا أعلم وأستغفرك لما لا أعلم' WHERE id = 802;
UPDATE contents SET body = '٤٠- اللهم إني عبدُكَ، وابنُ عبدِكَ، وابنُ أَمَتِكَ، في قبضتِكَ، ناصيتي بيدك، ماضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قضاؤكَ، أسألُك بِكُلِّ اسمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ أو أنزلْتَهُ في كتابِكَ، أو عَلَّمْتَهُ أحدًا من خَلْقِكَ، أو استأثرتَ به في عِلْمِ الغيبِ عِنْدَكَ أن تجعلَ القرآنَ العظيمَ ربيعَ قلبي، ونورَ صدري، وجِلاءَ حُزني، وَذَهَابَ همِّي.', search = '٤٠- اللهم إني عبدك وابن عبدك وابن أمتك في قبضتك ناصيتي بيدك ماض في حكمك عدل في قضاؤك أسألك بكل اسم هو لك سميت به نفسك أو أنزلته في كتابك أو علمته أحدا من خلقك أو استأثرت به في علم الغيب عندك أن تجعل القرآن العظيم ربيع قلبي ونور صدري وجلاء حزني وذهاب همي' WHERE id = 806;
UPDATE contents SET body = '٤١- اللَّهُمَّ عَلِّمْني الكتابَ، والحِكْمَةَ، وفَقِّهْني في الدِّين.', search = '٤١- اللهم علمني الكتاب والحكمة وفقهني في الدين' WHERE id = 1995;
UPDATE contents SET body = '٤٢- اللهم إني أسألك العافية.', search = '٤٢- اللهم إني أسألك العافية' WHERE id = 1996;
UPDATE contents SET body = '٤٣- اللهم صَلِّ على مُحمدٍ، وعلى آلِ محمدٍ، وبارِكْ على محمدٍ، وعلى آلِ محمد، كما صليتَ، وباركتَ على إبراهيمَ، وآلِ إبراهيمَ، إنَّك حميدٌ مجيد.', search = '٤٣- اللهم صل على محمد وعلى آل محمد وبارك على محمد وعلى آل محمد كما صليت وباركت على إبراهيم وآل إبراهيم إنك حميد مجيد' WHERE id = 836;
-- title 83
UPDATE contents SET body = '٤٤-
QuranText[(3:193:194)]', search = '٤٤- 3193194' WHERE id = 646;
UPDATE contents SET body = '٤٥- ﴿ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ ١٥٥ وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ ﴾', search = '٤٥- ﴿ أنت ولينا فٱغۡفرۡ لنا وٱرۡحمۡناۖ وأنت خيۡر ٱلۡغفرين ١٥٥ وٱكۡتبۡ لنا في هذه ٱلدنۡيا حسنة وفي ٱلۡأخرة إنا هدۡنا إليۡكۚ ﴾' WHERE id = 610;
UPDATE contents SET body = '٤٦- ﴿ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ ﴾', search = '٤٦- ﴿ سبۡحنك تبۡت إليۡك وأنا۠ أول ٱلۡمؤۡمنين ﴾' WHERE id = 1997;
UPDATE contents SET body = '٤٧- «لا إله إلا اللهُ، واللهُ أكبرُ، لا إله إلا الله وحدَه، لا إله إلا الله، لا شريكَ له، لا إله إلا الله، له الملكُ، وله الحمدُ، لا إله إلا الله، ولا حَوْلَ ولا قوَّةَ إلَّا بالله».', search = '٤٧- «لا إله إلا الله والله أكبر لا إله إلا الله وحده لا إله إلا الله لا شريك له لا إله إلا الله له الملك وله الحمد لا إله إلا الله ولا حول ولا قوة إلا بالله»' WHERE id = 1998;
UPDATE contents SET body = '٤٨- يا ربِّ! أنتَ أنتَ، وأنا أنا، أنتَ العَوَّادُ بالمغفرةِ، وأنَا العوَّادُ بالذُّنوب.', search = '٤٨- يا رب! أنت أنت وأنا أنا أنت العواد بالمغفرة وأنا العواد بالذنوب' WHERE id = 1999;
UPDATE contents SET body = '٤٩- اللهم إني أسألُكَ بأني أشهدُ أنك أنت اللهُ الذي لا إله إلا أنت، الأحدُ الصَّمَدُ، الذي لم يَلِدْ ولم يُولَدْ ولم يكن له كُفُوًا أحد، أن تغفرَ لي ذنوبي، إنك أنت الغفورُ الرحيمُ.', search = '٤٩- اللهم إني أسألك بأني أشهد أنك أنت الله الذي لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم' WHERE id = 2000;
UPDATE contents SET body = '٥٠- اللهم إني ظلمتُ نفسي ظُلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنتَ، فاغفر لي مغفرةً مِن عِنْدِكَ، وارحمني، إنك أنت الغفورُ الرحيم.', search = '٥٠- اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم' WHERE id = 773;
UPDATE contents SET body = '٥١- اللهم باعِدْ بيني وبين خطايايَ كما باعدتَ بين المشرقِ والمغرب، اللهم نَقِّنِي مِنْ خطاياي كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ، اللهم اغسلني من خطاياي بالماء والثلج والبَرَد.', search = '٥١- اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس اللهم اغسلني من خطاياي بالماء والثلج والبرد' WHERE id = 2001;
UPDATE contents SET body = '٥٢- اللهم اغفر لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ وما أعلنتُ، وما أسرفتُ، وما أنتَ أعلمُ به مني، أنت المقدِّمُ، وأنت المؤخِّرُ، لا إله إلا أنت.', search = '٥٢- اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت' WHERE id = 2002;
UPDATE contents SET body = '٥٣- اللهم اغفر لي ذنبي كُلَّه، ودِقَّه وجِلَّه، وأوله وآخِرَه، وعلانِيَتَهُ وسِرَّه.', search = '٥٣- اللهم اغفر لي ذنبي كله ودقه وجله وأوله وآخره وعلانيته وسره' WHERE id = 2003;
UPDATE contents SET body = '٥٤- اللهم إني أسألُكَ من الخيرِ كُلِّهِ، عَاجِلِهِ وآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلم، وأعوذُ بكَ من الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلمْ، اللهم إني أسألك الجنةَ، وما قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَو عَمَل، وأعوذُ بك من النَّارِ، وما قرَّب إليها من قول أو عمل، اللهم إني أسألك من خير ما سألك عبدُكَ ورسولُك محمد ﷺ، وأعوذ بك من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُك محمدٌ ﷺ، وأسألك ما قضيتَ لِي مِنْ أَمْرٍ أن تجعلَ عاقِبَتَهُ لِي رَشَدًا.', search = '٥٤- اللهم إني أسألك من الخير كله عاجله وآجله ما علمت منه وما لم أعلم وأعوذ بك من الشر كله عاجله وآجله ما علمت منه وما لم أعلم اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل وأعوذ بك من النار وما قرب إليها من قول أو عمل اللهم إني أسألك من خير ما سألك عبدك ورسولك محمد وأعوذ بك من شر ما استعاذك منه عبدك ورسولك محمد وأسألك ما قضيت لي من أمر أن تجعل عاقبته لي رشدا' WHERE id = 613;
UPDATE contents SET body = '٥٥- اللهم إني أعوذُ بك من العجزِ والكَسَلِ، والجُبْنِ والبُخْلِ، والهَرَمِ، وعذابِ القبر، اللهم آتِ نفسي تقواها، وزَكِّها أنت خَيْرُ مَن زَكَّاها، أنت وليُّها ومولاها، اللهم إني أعوذ بك من علمٍ لا ينفع، ومن قلبٍ لا يخشع، ومن نفسٍ لا تشبع، ومن دعوةٍ لا يُستجاب لها.', search = '٥٥- اللهم إني أعوذ بك من العجز والكسل والجبن والبخل والهرم وعذاب القبر اللهم آت نفسي تقواها وزكها أنت خير من زكاها أنت وليها ومولاها اللهم إني أعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن نفس لا تشبع ومن دعوة لا يستجاب لها' WHERE id = 732;
UPDATE contents SET body = '٥٦- اللهم إني أعوذ بك من يومِ السُّوء، ومن ليلةِ السُّوء، ومن ساعةِ السوء، ومن صاحبِ السُّوء، ومن جارِ السُّوءِ في دَارِ المُقامَةِ.', search = '٥٦- اللهم إني أعوذ بك من يوم السوء ومن ليلة السوء ومن ساعة السوء ومن صاحب السوء ومن جار السوء في دار المقامة' WHERE id = 799;
UPDATE contents SET body = '٥٧- اللهم إني أسألك فِعْلَ الخيراتِ، وتَرْكَ المنكرات، وحُبَّ المساكين، وأن تغفرَ لي وترحمَني، وإذا أردتَ فِتنةَ قومٍ فتوفَّني غَيْرَ مفتونٍ، أسألُكَ حُبَّكَ، وحُبَّ مَنْ يُحِبُّكَ، وحُبَّ عَمَلٍ يُقَرِّبُ إلى حُبِّك.', search = '٥٧- اللهم إني أسألك فعل الخيرات وترك المنكرات وحب المساكين وأن تغفر لي وترحمني وإذا أردت فتنة قوم فتوفني غير مفتون أسألك حبك وحب من يحبك وحب عمل يقرب إلى حبك' WHERE id = 632;
UPDATE contents SET body = '٥٨- اللهم إني أسألُكَ المعافاةَ في الدُّنيا والآخرة.', search = '٥٨- اللهم إني أسألك المعافاة في الدنيا والآخرة' WHERE id = 852;
UPDATE contents SET body = '٥٩- اللهم لا تُخْزِنِي يومَ القيامةِ.', search = '٥٩- اللهم لا تخزني يوم القيامة' WHERE id = 2004;
UPDATE contents SET body = '٦٠- اللهم إني أسألُكَ الجَنَّةَ، وأعوذُ بِكَ مِنَ النَّار.', search = '٦٠- اللهم إني أسألك الجنة وأعوذ بك من النار' WHERE id = 2005;
UPDATE contents SET body = '٦١- اللهم هَبِ المُسيئينَ مِنَّا للمُحْسِنِينَ، وأَعْطِ مُحْسِنَنَا ما سَأَلَ.', search = '٦١- اللهم هب المسيئين منا للمحسنين وأعط محسننا ما سأل' WHERE id = 714;
UPDATE contents SET body = '٦٢- اللهم أَنْجِ المستَضْعَفينَ من المؤمنين.', search = '٦٢- اللهم أنج المستضعفين من المؤمنين' WHERE id = 2006;
UPDATE contents SET body = '٦٣- اللهم صَلِّ على مُحَمَّدٍ وعلى أَهْلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما صَلَّيْتَ على آلِ إبراهيمَ، إنك حميدٌ مجيدٌ، وبَارِكْ على محمدٍ، وعلى آلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما باركت على آلِ إبراهيمَ، إنك حميدٌ مجيد.', search = '٦٣- اللهم صل على محمد وعلى أهل بيته وعلى أزواجه وذريته كما صليت على آل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل بيته وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد' WHERE id = 2007;
-- title 84
UPDATE contents SET body = '٦٤-
QuranText[(3:53:53)]', search = '٦٤- 35353' WHERE id = 606;
UPDATE contents SET body = '٦٥- ﴿ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ﴾', search = '٦٥- ﴿ رب إني لما أنزلۡت إلي منۡ خيۡر فقير ﴾' WHERE id = 688;
UPDATE contents SET body = '٦٦-
QuranText[(37:100:100)]', search = '٦٦- 37100100' WHERE id = 2008;
UPDATE contents SET body = '٦٧- ﴿ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ﴾', search = '٦٧- ﴿ رب هبۡ لي من لدنك ذرية طيبةۖ إنك سميع ٱلدعاء ﴾' WHERE id = 2009;
UPDATE contents SET body = '٦٨- لا إله إلا اللهُ العظيمُ الحليم، لا إله إلَّا الله ربُّ العرشِ العظيم، لا إله إلا الله ربُّ السماواتِ والأرضِ، لا إله إلا اللهُ ربُّ العرشِ الكريم.', search = '٦٨- لا إله إلا الله العظيم الحليم لا إله إلا الله رب العرش العظيم لا إله إلا الله رب السماوات والأرض لا إله إلا الله رب العرش الكريم' WHERE id = 2010;
UPDATE contents SET body = '٦٩- اللهم اقْسِمْ لَنَا من خَشْيَتِكَ ما تحولُ به بيننا وبين معاصيك، ومن طاعتك ما تُبَلِّغُنا به جنتَك، ومن اليقينِ ما تُهَوِّنُ به علينا مصائبَ الدُّنيا، ومَتِّعْنا بأسماعِنا، وأبصارِنا، وقُوَّتِنا ما أحييتَنا، واجعلْه الوَارِثَ مِنَّا، واجعل ثأرَنا على مَن ظَلَمَنَا، وانصُرْنا على مَن عادانا، ولا تجعلْ مصيبتَنا في دينِنا، ولا تجعلِ الدنيا أكبرَ هَمِّنا، ولا مَبْلَغَ عِلْمِنا، ولا تُسَلِّطْ علينا من لا يرحمُنا.', search = '٦٩- اللهم اقسم لنا من خشيتك ما تحول به بيننا وبين معاصيك ومن طاعتك ما تبلغنا به جنتك ومن اليقين ما تهون به علينا مصائب الدنيا ومتعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا واجعله الوارث منا واجعل ثأرنا على من ظلمنا وانصرنا على من عادانا ولا تجعل مصيبتنا في ديننا ولا تجعل الدنيا أكبر همنا ولا مبلغ علمنا ولا تسلط علينا من لا يرحمنا' WHERE id = 713;
UPDATE contents SET body = '٧٠- اللهم اغفر لي ما أسررتُ وما أعلنتُ.', search = '٧٠- اللهم اغفر لي ما أسررت وما أعلنت' WHERE id = 2011;
UPDATE contents SET body = '٧١- اللهم اغفر لي ذنبي، وخطئي وعَمْدي، اللهم إني أستهديك لأرشَدِ أمري، وأعوذُ بك من شَرِّ نفسي.', search = '٧١- اللهم اغفر لي ذنبي وخطئي وعمدي اللهم إني أستهديك لأرشد أمري وأعوذ بك من شر نفسي' WHERE id = 734;
UPDATE contents SET body = '٧٢- ربِّ أسألك العافيةَ والمعافاةَ في الدنيا والآخرة.', search = '٧٢- رب أسألك العافية والمعافاة في الدنيا والآخرة' WHERE id = 2012;
UPDATE contents SET body = '٧٣- اللهم ربنا آتنا في الدُّنيا حسنة، وفي الآخرةِ حسنةً، وَقِنا عذابَ النَّارِ.', search = '٧٣- اللهم ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار' WHERE id = 712;
UPDATE contents SET body = '٧٤- اللهم اجعلْني مِفْتَاحًا للخيرِ مِغْلاقًا للشرِّ، ولا تجعلني مِفْتاحًا للشر مِغْلاقًا للخير.', search = '٧٤- اللهم اجعلني مفتاحا للخير مغلاقا للشر ولا تجعلني مفتاحا للشر مغلاقا للخير' WHERE id = 805;
UPDATE contents SET body = '٧٥- اللهم لك الحمدُ كُلُّه، اللهم لا قابضَ لما بَسَطتَ، ولا باسطَ لما قبضتَ، ولا هادِيَ لِمَا أَضْلَلْتَ، ولا مُضِلَّ لِمَن هَدَيْتَ، ولا مُعْطِيَ لما منَعْت، ولا مَانِعَ لما أَعْطَيْتَ، ولا مُقَرِّبَ لما باعَدْتَ، وَلا مُبَاعِدَ لما قَرَّبْتَ، اللهُمَّ ابْسُطْ علينا مِنْ بَرَكَاتِكَ ورَحْمَتِكَ وفَضْلِكَ ورِزْقِكَ، اللهم إني أسألُكَ النَّعيمَ المقيمَ الذي لا يَحُولُ ولا يزول، اللهُمَّ إني أسألك النعيمَ يَوْمَ العَيْلَةِ، والأمنَ يومَ الخوفِ، اللهُمَّ إني عائذٌ بِكَ مِنْ شَرِّ ما أَعْطَيْتَنَا وَشَرِّ ما مَنَعْتَنا، اللهُمَّ حَبِّبْ إلينا الإيمانَ، وزَيِّنْهُ في قلوبنا، وكرِّهْ إلينا الكفرَ والفسوقَ والعصيانَ، واجعلنا من الراشدين، اللهُمَّ تَوَفَّنا مسلمين، وأحْيِنا مسلمين، وألحِقنا بالصالحين غَيْرَ خَزايا ولا مفتونين، اللهُمَّ قَاتِلِ الكَفَرَةَ الَّذين يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّون عن سبيلِكَ، واجْعَل عليهم رِجْزَكَ وعَذَابَكَ، اللهُمَّ قَاتِلِ الكفرةَ الذين أُوتُوا الكتابَ، إلهَ الحقِّ.', search = '٧٥- اللهم لك الحمد كله اللهم لا قابض لما بسطت ولا باسط لما قبضت ولا هادي لما أضللت ولا مضل لمن هديت ولا معطي لما منعت ولا مانع لما أعطيت ولا مقرب لما باعدت ولا مباعد لما قربت اللهم ابسط علينا من بركاتك ورحمتك وفضلك ورزقك اللهم إني أسألك النعيم المقيم الذي لا يحول ولا يزول اللهم إني أسألك النعيم يوم العيلة والأمن يوم الخوف اللهم إني عائذ بك من شر ما أعطيتنا وشر ما منعتنا اللهم حبب إلينا الإيمان وزينه في قلوبنا وكره إلينا الكفر والفسوق والعصيان واجعلنا من الراشدين اللهم توفنا مسلمين وأحينا مسلمين وألحقنا بالصالحين غير خزايا ولا مفتونين اللهم قاتل الكفرة الذين يكذبون رسلك ويصدون عن سبيلك واجعل عليهم رجزك وعذابك اللهم قاتل الكفرة الذين أوتوا الكتاب إله الحق' WHERE id = 2013;
UPDATE contents SET body = '٧٦- اللهم أنت المَلِكُ، لا إله إلا أنت، سبحانك وبحمدك، أنت ربي، وأنا عبدُك، ظلمتُ نفسي، واعترفتُ بذنبي، فاغفر لي ذنوبي جميعًا، إنه لا يغفر الذنوبَ إلا أنت، واهْدِنِي لأحسنِ الأخلاقِ، لا يَهْدِي لأحسنِها إلا أنتَ، واصرِفْ عني سَيِّئَها، لا يصرفُ عني سيئَها إلا أنت، لَبَّيْكَ وسَعْدَيْكَ والخيرُ كُلُّه في يديك، والشرُّ ليس إليك، والمَهْدِيُّ مَن هَدَيْتَ، أنا بك وإليك، لا مَنْجا ولا ملجأ مِنكَ إلا إليك، تباركتَ وتعاليتَ، أستغفرُك، وأتوبُ إليك.', search = '٧٦- اللهم أنت الملك لا إله إلا أنت سبحانك وبحمدك أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي فاغفر لي ذنوبي جميعا إنه لا يغفر الذنوب إلا أنت واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت واصرف عني سيئها لا يصرف عني سيئها إلا أنت لبيك وسعديك والخير كله في يديك والشر ليس إليك والمهدي من هديت أنا بك وإليك لا منجا ولا ملجأ منك إلا إليك تباركت وتعاليت أستغفرك وأتوب إليك' WHERE id = 2014;
UPDATE contents SET body = '٧٧- اللهم إني أعوذ بك من فتنةِ النار، وعذابِ النار، وفتنةِ القبر، وعذابِ القبر، ومن شَرِّ فتنةِ الغِنَى، ومن شرِّ فتنةِ الفقر، وأعوذ بك من شرِّ فتنةِ المسيح الدَّجَّال، اللهُمَّ اغْسِلْ خطايايَ بماءِ الثَّلْجِ والبَرَدِ، ونَقِّ قلبي من الخطايا كما نَقَّيتَ الثوبَ الأبيضَ من الدَّنَسِ، وباعِدْ بيني وبين خطايايَ كما باعدْتَ بين المشرقِ والمغربِ، اللهم إني أعوذُ بِكَ من الكَسَلِ والهَرَمِ، والمأثَمِ والمغرم.', search = '٧٧- اللهم إني أعوذ بك من فتنة النار وعذاب النار وفتنة القبر وعذاب القبر ومن شر فتنة الغنى ومن شر فتنة الفقر وأعوذ بك من شر فتنة المسيح الدجال اللهم اغسل خطاياي بماء الثلج والبرد ونق قلبي من الخطايا كما نقيت الثوب الأبيض من الدنس وباعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب اللهم إني أعوذ بك من الكسل والهرم والمأثم والمغرم' WHERE id = 770;
UPDATE contents SET body = '٧٨- اللهُمَّ صَلِّ على مُحَمَّدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيم، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ.', search = '٧٨- اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم' WHERE id = 2015;
