UPDATE contents SET body = '١٠٤- ﴿ رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', search = '١٠٤- ﴿ ربنا ظلمۡنا أنفسنا وإن لمۡ تغۡفرۡ لنا وترۡحمۡنا لنكونن من ٱلۡخسرين ﴾' WHERE id = 833;
UPDATE contents SET body = '١٠٥- ﴿ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', search = '١٠٥- ﴿ لئن لمۡ يرۡحمۡنا ربنا ويغۡفرۡ لنا لنكونن من ٱلۡخسرين ﴾' WHERE id = 2027;
UPDATE contents SET body = '١٠٦- ﴿ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴾', search = '١٠٦- ﴿ ربنا إننا ءامنا فٱغۡفرۡ لنا ذنوبنا وقنا عذاب ٱلنار ﴾' WHERE id = 626;
UPDATE contents SET body = '١٠٧- ﴿ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ ٧ رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨ وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴾', search = '١٠٧- ﴿ ربنا وسعۡت كل شيۡء رحۡمة وعلۡما فٱغۡفرۡ للذين تابوا وٱتبعوا سبيلك وقهمۡ عذاب ٱلۡجحيم ٧ ربنا وأدۡخلۡهمۡ جنت عدۡن ٱلتي وعدتهمۡ ومن صلح منۡ ءابائهمۡ وأزۡوجهمۡ وذريتهمۡۚ إنك أنت ٱلۡعزيز ٱلۡحكيم ٨ وقهم ٱلسياتۚ ومن تق ٱلسيات يوۡمئذ فقدۡ رحمۡتهۥۚ وذلك هو ٱلۡفوۡز ٱلۡعظيم ﴾' WHERE id = 747;
UPDATE contents SET body = '١٠٨- ﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ﴾', search = '١٠٨- ﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأصۡلحۡ لي في ذريتيۖ إني تبۡت إليۡك وإني من ٱلۡمسۡلمين ﴾' WHERE id = 725;
UPDATE contents SET body = '١٠٩- ﴿ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ﴾', search = '١٠٩- ﴿ ربنا هبۡ لنا منۡ أزۡوجنا وذريتنا قرة أعۡين وٱجۡعلۡنا للۡمتقين إماما ﴾' WHERE id = 709;
UPDATE contents SET body = '١١٠- اللهم لك الحمدُ، أنت نورُ السماواتِ والأرضِ ومَنْ فيهنَّ، ولك الحمدُ، أنت قيِّمُ السماواتِ والأرضِ ومَن فيهنَّ، ولك الحمدُ، أنت مَلِكُ السماواتِ والأرضِ ومن فيهنَّ، ولك الحمدُ، أنت الحقُّ، ووعدُك حقٌّ، وقولُك حقٌّ، ولقاؤكَ حقٌّ، والجنةُ حقٌّ، والنارُ حقٌّ، والساعةُ حقٌّ، والنبيُّون حقٌّ، ومحمدٌ حقٌّ، اللهم لك أسلمتُ، وعليك توكلتُ، وبك آمنتُ، وإليك أنبتُ، وبك خاصمتُ، وإليك حاكَمْتُ، أنت رَبُّنا، وإليكَ المصير، فاغفر لي ما قدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ، وما أعلنتُ، وما أنت أعلمُ به مني، أنت المقدِّمُ، وأنت المؤخِّرُ، أنت إلهي لا إله إلا أنت، ولا حولَ ولا قوةَ إلا بك.', search = '١١٠- اللهم لك الحمد أنت نور السماوات والأرض ومن فيهن ولك الحمد أنت قيم السماوات والأرض ومن فيهن ولك الحمد أنت ملك السماوات والأرض ومن فيهن ولك الحمد أنت الحق ووعدك حق وقولك حق ولقاؤك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق اللهم لك أسلمت وعليك توكلت وبك آمنت وإليك أنبت وبك خاصمت وإليك حاكمت أنت ربنا وإليك المصير فاغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر أنت إلهي لا إله إلا أنت ولا حول ولا قوة إلا بك' WHERE id = 2028;
UPDATE contents SET body = '١١١- سبحانَ اللهِ وبحمدِه، أستغفرُ اللهَ وأتوبُ إليه.', search = '١١١- سبحان الله وبحمده أستغفر الله وأتوب إليه' WHERE id = 2029;
UPDATE contents SET body = '١١٢- اللهم اغفر لي ذنبي، وأدخِلْني يومَ القيامةِ مُدْخَلًا كريمًا.', search = '١١٢- اللهم اغفر لي ذنبي وأدخلني يوم القيامة مدخلا كريما' WHERE id = 2030;
UPDATE contents SET body = '١١٣- اللهم ربَّ جبرائيلَ وميكائيلَ، وربَّ إسرافيلَ، أعوذُ بك من حَرِّ النارِ، وعذابِ القبر.', search = '١١٣- اللهم رب جبرائيل وميكائيل ورب إسرافيل أعوذ بك من حر النار وعذاب القبر' WHERE id = 2031;
UPDATE contents SET body = '١١٤- اللهم جَنِّبْني مُنكَراتِ الأخلاقِ والأهواءِ والأعمالِ والأدواءِ.', search = '١١٤- اللهم جنبني منكرات الأخلاق والأهواء والأعمال والأدواء' WHERE id = 2032;
UPDATE contents SET body = '١١٥- اللهم إني أسألك الهدى، والتُّقى، والعفافَ، والغِنى.', search = '١١٥- اللهم إني أسألك الهدى والتقى والعفاف والغنى' WHERE id = 698;
UPDATE contents SET body = '١١٦- اللهم إني أسألُكَ الثَّباتَ في الأمر، والعزيمةَ على الرُّشْدِ، وأسألُكَ مُوجِباتِ رحمتِكَ، وعزائمَ مغفرتِك، وأسألك شُكْرَ نعمتِك، وحُسْنَ عبادتِكَ، وأسألك قلبًا سليمًا، ولسانًا صادقًا، وأسألُكَ مِن خيرِ ما تَعْلَمُ، وأعوذُ بِكَ مِن شَرِّ ما تَعْلَمُ، وأستغفرك لما تعلمُ، إنَّكَ أنتَ علام الغيوب.', search = '١١٦- اللهم إني أسألك الثبات في الأمر والعزيمة على الرشد وأسألك موجبات رحمتك وعزائم مغفرتك وأسألك شكر نعمتك وحسن عبادتك وأسألك قلبا سليما ولسانا صادقا وأسألك من خير ما تعلم وأعوذ بك من شر ما تعلم وأستغفرك لما تعلم إنك أنت علام الغيوب' WHERE id = 2033;
UPDATE contents SET body = '١١٧- اللهم إني أعوذ بعظمتِكَ أن أُغْتَالَ مِنْ تحتي.', search = '١١٧- اللهم إني أعوذ بعظمتك أن أغتال من تحتي' WHERE id = 2034;
UPDATE contents SET body = '١١٨- اللهم إني أعوذ بكَ من الجوعِ، فإنه بِئْسَ الضجيعُ، وأعوذ بك من الخيانة، فإنها بِئْسَتِ البطانةُ.', search = '١١٨- اللهم إني أعوذ بك من الجوع فإنه بئس الضجيع وأعوذ بك من الخيانة فإنها بئست البطانة' WHERE id = 694;
UPDATE contents SET body = '١١٩- اللهم إني أعوذ بك من الفقرِ والقِلَّةِ، والذِّلَّةِ، وأعوذ بك أن أَظْلِمَ أو أُظْلَمَ.', search = '١١٩- اللهم إني أعوذ بك من الفقر والقلة والذلة وأعوذ بك أن أظلم أو أظلم' WHERE id = 733;
UPDATE contents SET body = '١٢٠- اللهم أكثِرْ مالي وولدي، وبارك لي فيما أعطيتني.', search = '١٢٠- اللهم أكثر مالي وولدي وبارك لي فيما أعطيتني' WHERE id = 2035;
UPDATE contents SET body = '١٢١- اللهم اجعلْ أوسعَ رزقِكَ عليَّ عند كِبَرِ سِنِّي، وانقطاعِ عُمُري.', search = '١٢١- اللهم اجعل أوسع رزقك علي عند كبر سني وانقطاع عمري' WHERE id = 693;
UPDATE contents SET body = '١٢٢- اللهم حاسبني حسابًا يسيرًا.', search = '١٢٢- اللهم حاسبني حسابا يسيرا' WHERE id = 857;
UPDATE contents SET body = '١٢٣- اللهم أحيني مِسكينًا، وأمِتْني مِسْكينًا، واحشُرْني في زُمْرَةِ المساكين.', search = '١٢٣- اللهم أحيني مسكينا وأمتني مسكينا واحشرني في زمرة المساكين' WHERE id = 691;
UPDATE contents SET body = '١٢٤- اللهُمَّ صُبَّ عَلَيَّ الخيرَ صَبًّا، ولا تَجْعَلْ عَيْشِي كَدًّا كَدًّا.', search = '١٢٤- اللهم صب علي الخير صبا ولا تجعل عيشي كدا كدا' WHERE id = 2036;
UPDATE contents SET body = '١٢٥- اللهم صَلِّ على محمدٍ وعلى أزواجه وذُرِّيَّتِه، كما صليتَ على آلِ إبراهيمَ، وبارِكْ على مُحمدٍ وعلى أزواجه وذريته، كما باركت على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ.', search = '١٢٥- اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد' WHERE id = 752;
-- title 87
UPDATE contents SET body = '١٢٦- ﴿ ... ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٦ تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ ﴾', search = '١٢٦- ﴿ ٱللهم ملك ٱلۡملۡك تؤۡتي ٱلۡملۡك من تشاء وتنزع ٱلۡملۡك ممن تشاء وتعز من تشاء وتذل من تشاءۖ بيدك ٱلۡخيۡرۖ إنك على كل شيۡء قدير ٢٦ تولج ٱليۡل في ٱلنهار وتولج ٱلنهار في ٱليۡلۖ وتخۡرج ٱلۡحي من ٱلۡميت وتخۡرج ٱلۡميت من ٱلۡحيۖ وترۡزق من تشاء بغيۡر حساب ﴾' WHERE id = 2037;
UPDATE contents SET body = '١٢٧- اللهم ارزُقْنا ﴿ وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ ﴾', search = '١٢٧- اللهم ارزقنا ﴿ وأنت خيۡر ٱلرزقين ﴾' WHERE id = 2038;
UPDATE contents SET body = '١٢٨- لا إله إلا اللهُ الحليمُ الكريمُ، لا إله إلا اللهُ العَلِيُّ العظيمُ، لا إله إلا اللهُ ربُّ السماواتِ السبعِ، وربُّ العرشِ الكريم.', search = '١٢٨- لا إله إلا الله الحليم الكريم لا إله إلا الله العلي العظيم لا إله إلا الله رب السماوات السبع ورب العرش الكريم' WHERE id = 793;
UPDATE contents SET body = '١٢٩- اللهم إنَّكَ عَفُوٌّ تُحِبُّ العفوَ، فاعفُ عَنِّي.', search = '١٢٩- اللهم إنك عفو تحب العفو فاعف عني' WHERE id = 2039;
UPDATE contents SET body = '١٣٠- لا إلهَ إلا أنتَ، سُبحانَكَ إني كُنتُ من الظالمين.', search = '١٣٠- لا إله إلا أنت سبحانك إني كنت من الظالمين' WHERE id = 727;
UPDATE contents SET body = '١٣١- رَبِّ اغفِرْ وارحَمْ، إنَّك أنتَ الأَعَزُّ الأكرم.', search = '١٣١- رب اغفر وارحم إنك أنت الأعز الأكرم' WHERE id = 2040;
UPDATE contents SET body = '١٣٢- اللهم رَبِّ اغفِر لي خطيئتي وجهلي، وإسرافي في أمري، وما أنتَ أعلمُ به مني، اللهم اغفِر لي جِدِّي وهَزْلِي، وخَطَئِي وعَمْدِي، وكُلُّ ذلك عِنْدي، اللهُمَّ اغفِر لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أَسْرَرْتُ، وما أعلنتُ، وما أنتَ أعلمُ به مِنِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، وأنتَ على كُلِّ شيءٍ قديرٌ.', search = '١٣٢- اللهم رب اغفر لي خطيئتي وجهلي وإسرافي في أمري وما أنت أعلم به مني اللهم اغفر لي جدي وهزلي وخطئي وعمدي وكل ذلك عندي اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر وأنت على كل شيء قدير' WHERE id = 768;
UPDATE contents SET body = '١٣٣- اللهم بعلمِكَ الغيبَ، وقُدْرَتِكَ على الخَلْقِ، أحيِني ما عَلِمْتَ الحياةَ خيرًا لي، وتَوَفَّنِي إذا علمتَ الوفاةَ خيرًا لي، اللهُم وأسألُكَ خشيتَكَ في الغيبِ والشهادة، وأسألُكَ كلمةَ الحقِّ في الرضى والغضب، وأسألُك القَصْدَ في الفقرِ والغِنى، وأسألُكَ نعيمًا لا يَنفدُ، وأسألُك قُرَّةَ عينٍ لا تنقطعُ، وأسألُك الرِّضى بعدَ القضاءِ، وأسألُك بَرْدَ الْعَيْشِ بَعْدَ الموتِ، وأسألُك لَذَّةَ النظرِ إلى وجهِكَ، والشوقَ إلى لقائك، في غيرِ ضَرَّاءَ مُضِرَّةٍ، ولا فتنةٍ مُضِلَّة، اللهم زَيِّنَّا بزينةِ الإيمانِ، واجعلْنا هُدَاةً مُهْتَدِين.', search = '١٣٣- اللهم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا علمت الوفاة خيرا لي اللهم وأسألك خشيتك في الغيب والشهادة وأسألك كلمة الحق في الرضى والغضب وأسألك القصد في الفقر والغنى وأسألك نعيما لا ينفد وأسألك قرة عين لا تنقطع وأسألك الرضى بعد القضاء وأسألك برد العيش بعد الموت وأسألك لذة النظر إلى وجهك والشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة اللهم زينا بزينة الإيمان واجعلنا هداة مهتدين' WHERE id = 695;
UPDATE contents SET body = '١٣٤- اللهم اغفِرْ لي، واجعلني يومَ القيامةِ فوقَ كثيرٍ من خَلْقِكَ.', search = '١٣٤- اللهم اغفر لي واجعلني يوم القيامة فوق كثير من خلقك' WHERE id = 2041;
UPDATE contents SET body = '١٣٥- اللهُمَّ اغفِرْ لي ذنبي، وأدخِلْني يومَ القيامةِ مُدْخَلًا كريمًا.', search = '١٣٥- اللهم اغفر لي ذنبي وأدخلني يوم القيامة مدخلا كريما' WHERE id = 2042;
UPDATE contents SET body = '١٣٦- اللهم اغفِرْ لنا وارحمنا، وآتِنا في الدنيا حَسَنَةً، وفي الآخرةِ حسنةً، وقِنَا عذابَ النار.', search = '١٣٦- اللهم اغفر لنا وارحمنا وآتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار' WHERE id = 2043;
UPDATE contents SET body = '١٣٧- اللهم إني أسألك العافيةَ في الدنيا والآخرة.', search = '١٣٧- اللهم إني أسألك العافية في الدنيا والآخرة' WHERE id = 2044;
UPDATE contents SET body = '١٣٨- اللهم اكْفِني بِحَلالِكَ عن حَرَامِكَ، وأَغْنِنِي بفضلِكَ عَمَّن سِواك.', search = '١٣٨- اللهم اكفني بحلالك عن حرامك وأغنني بفضلك عمن سواك' WHERE id = 692;
UPDATE contents SET body = '١٣٩- اللهم إني أعوذُ بك من قولٍ لا يُسمَعُ، وعملٍ لا يُرفَعُ، وقلبٍ لا يَخْشَعُ، وعلمٍ لا يَنفع.', search = '١٣٩- اللهم إني أعوذ بك من قول لا يسمع وعمل لا يرفع وقلب لا يخشع وعلم لا ينفع' WHERE id = 2045;
UPDATE contents SET body = '١٤٠- اللهم إني أعوذ بك من الكسل والهَرَم، والمَغْرَمِ والمأثم، وأعوذ بك من شرِّ المسيح الدجال، وأعوذ بك من عذابِ القبرِ، وأعوذ بك من عذاب النار.', search = '١٤٠- اللهم إني أعوذ بك من الكسل والهرم والمغرم والمأثم وأعوذ بك من شر المسيح الدجال وأعوذ بك من عذاب القبر وأعوذ بك من عذاب النار' WHERE id = 2046;
UPDATE contents SET body = '١٤١- اللهم مَنْ وَلِي مِنْ أمرِ أُمَّةِ محمدٍ ﷺ شيئًا فَشَقَّ عليهم، فاشْقُقْ عليه، ومن وَلِيَ مِنْ أمرِ أمةِ محمدٍ ﷺ شيئًا فَرفَقَ بهم، فارفُقْ به.', search = '١٤١- اللهم من ولي من أمر أمة محمد شيئا فشق عليهم فاشقق عليه ومن ولي من أمر أمة محمد شيئا فرفق بهم فارفق به' WHERE id = 771;
UPDATE contents SET body = '١٤٢- اللهُمَّ صَلِّ على محمدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على مُحمدٍ النبيِّ الأُمِّيِّ، وعلى آلِ مُحمدٍ، كما بارَكْتَ على آلِ إبراهيمَ في العالمينَ، إنَّك حميدٌ مجيدٌ.', search = '١٤٢- اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد' WHERE id = 2047;
-- title 88
UPDATE contents SET body = '١٤٣- ﴿ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ٤ رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴾', search = '١٤٣- ﴿ ربنا عليۡك توكلۡنا وإليۡك أنبۡنا وإليۡك ٱلۡمصير ٤ ربنا لا تجۡعلۡنا فتۡنة للذين كفروا وٱغۡفرۡ لنا ربناۖ إنك أنت ٱلۡعزيز ٱلۡحكيم ﴾' WHERE id = 710;
UPDATE contents SET body = '١٤٤- ربنا أدخِلْنا ﴿ مَعَ ٱلۡقَوۡمِ ٱلصَّٰلِحِينَ ﴾', search = '١٤٤- ربنا أدخلنا ﴿ مع ٱلۡقوۡم ٱلصلحين ﴾' WHERE id = 2048;
