UPDATE contents SET body = '١٤٧- ﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', search = '١٤٧- ﴿ حسۡبي ٱلله لا إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾' WHERE id = 2049;
UPDATE contents SET body = '١٤٨- ﴿ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ﴾', search = '١٤٨- ﴿ وأفوض أمۡري إلى ٱللهۚ إن ٱلله بصيرۢ بٱلۡعباد ﴾' WHERE id = 2050;
UPDATE contents SET body = '١٤٩- ﴿ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴾', search = '١٤٩- ﴿ وما توۡفيقي إلا بٱللهۚ عليۡه توكلۡت وإليۡه أنيب ﴾' WHERE id = 2051;
UPDATE contents SET body = '١٥٠- ﴿ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴾', search = '١٥٠- ﴿ إن ٱلۡحكۡم إلا للهۖ عليۡه توكلۡتۖ وعليۡه فلۡيتوكل ٱلۡمتوكلون ﴾' WHERE id = 2052;
UPDATE contents SET body = '١٥١- اللهُ اللهُ رَبِّي، لا أُشْرِكُ بِهِ شيئًا.', search = '١٥١- الله الله ربي لا أشرك به شيئا' WHERE id = 2053;
UPDATE contents SET body = '١٥٢- لا إلهَ إلَّا اللهُ وحدَه، لا شريكَ له، اللهُ أكبرُ كبيرًا، والحمدُ لله كثيرًا، وسبحانَ اللهِ ربِّ العالمين، لا حولَ ولا قوَّةَ إلَّا باللهِ العزيزِ الحكيم، اللَّهُمَّ اغفِرْ لي، وارحمْني، واهدِني، وارزُقْني، وعافِني.', search = '١٥٢- لا إله إلا الله وحده لا شريك له الله أكبر كبيرا والحمد لله كثيرا وسبحان الله رب العالمين لا حول ولا قوة إلا بالله العزيز الحكيم اللهم اغفر لي وارحمني واهدني وارزقني وعافني' WHERE id = 631;
UPDATE contents SET body = '١٥٣- اللهُمَّ حَبِّبْ إِلَيَّ لقاءَكَ، وسَهِّلْ عَلَيَّ قضاءَكَ، وأَقْلِلْ لي من الدُّنيا.', search = '١٥٣- اللهم حبب إلي لقاءك وسهل علي قضاءك وأقلل لي من الدنيا' WHERE id = 2054;
UPDATE contents SET body = '١٥٤- رَضِينا باللهِ ربًّا، وبالإسلامِ دِينًا، وبمحمدٍ رَسُولًا، نعوذُ بالله مِنْ سُوءِ الفِتَن.', search = '١٥٤- رضينا بالله ربا وبالإسلام دينا وبمحمد رسولا نعوذ بالله من سوء الفتن' WHERE id = 2055;
UPDATE contents SET body = '١٥٥- اللهم إنِّي أعوذُ بِكَ من العَجْزِ والكَسَلِ، والجُبْنِ والهَرَمِ، وأعوذُ بِكَ من عذابِ القَبْرِ، وأعوذُ بِكَ من فِتْنَةِ المحيا والممات.', search = '١٥٥- اللهم إني أعوذ بك من العجز والكسل والجبن والهرم وأعوذ بك من عذاب القبر وأعوذ بك من فتنة المحيا والممات' WHERE id = 774;
UPDATE contents SET body = '١٥٦- نعوذُ باللهِ من النارِ، نعوذُ باللهِ من الفتنِ؛ ما ظَهَرَ مِنْها، وما بَطَنَ، نعوذُ بالله من فِتنةِ الدَّجَّالِ.', search = '١٥٦- نعوذ بالله من النار نعوذ بالله من الفتن ما ظهر منها وما بطن نعوذ بالله من فتنة الدجال' WHERE id = 796;
UPDATE contents SET body = '١٥٧- اللهُمَّ إنَّا نعوذُ بِكَ أنْ نَرْجِعَ على أعقابِنا، أو نُفْتَنَ عن دِينِنا.', search = '١٥٧- اللهم إنا نعوذ بك أن نرجع على أعقابنا أو نفتن عن ديننا' WHERE id = 2056;
UPDATE contents SET body = '١٥٨- اللهم إنِّي أعوذُ بِكَ من الحَوْرِ بعدَ الكَوْنِ.', search = '١٥٨- اللهم إني أعوذ بك من الحور بعد الكون' WHERE id = 2057;
UPDATE contents SET body = '١٥٩- أعوذُ بِعِزَّتِكَ أنْ تُضِلَّنِي، لا إلهَ إلَّا أنتَ الحَيُّ الذي لا يموتُ، والجِنُّ والإنسُ يموتون.', search = '١٥٩- أعوذ بعزتك أن تضلني لا إله إلا أنت الحي الذي لا يموت والجن والإنس يموتون' WHERE id = 2058;
UPDATE contents SET body = '١٦٠- اللهُمَّ إنِّي أعوذُ بِوَجْهِكَ الكريم، وكلماتِكَ التَّامَّةِ مِنْ شَرِّ ما أنتَ آخِذٌ بناصِيَتِه، اللَّهُمَّ أنتَ تَكْشِفُ المَغْرَمَ والمأثَمَ، اللهُمَّ لا يُهْزَمُ جُنْدُكَ، ولا يُخْلَفُ وَعْدُكَ، ولا يَنْفَعُ ذا الجَدِّ مِنْكَ الجدُّ، سُبحانَكَ اللهُمَّ وبحمدِكَ.', search = '١٦٠- اللهم إني أعوذ بوجهك الكريم وكلماتك التامة من شر ما أنت آخذ بناصيته اللهم أنت تكشف المغرم والمأثم اللهم لا يهزم جندك ولا يخلف وعدك ولا ينفع ذا الجد منك الجد سبحانك اللهم وبحمدك' WHERE id = 2059;
UPDATE contents SET body = '١٦١- أعوذُ بكلماتِ اللهِ التَّامَّاتِ التي لا يُجاوِزُهُنَّ بَرٌّ ولا فاجِرٌ، من شَرِّ ما خَلَقَ وَذَرَأَ وبَرَأَ، ومن شَرِّ ما ينزلُ من السماءِ، ومن شرِّ ما يَعْرُجُ فيها، ومن شرِّ ما ذرأَ في الأرضِ وبرَأَ، ومن شرِّ ما يخرجُ منها، ومن شَرِّ فتنِ الليلِ والنهارِ، ومن شَرِّ كُلِّ طارقٍ يطرُقُ، إلَّا طارقًا يطرُقُ بخيرٍ يا رحمنُ.', search = '١٦١- أعوذ بكلمات الله التامات التي لا يجاوزهن بر ولا فاجر من شر ما خلق وذرأ وبرأ ومن شر ما ينزل من السماء ومن شر ما يعرج فيها ومن شر ما ذرأ في الأرض وبرأ ومن شر ما يخرج منها ومن شر فتن الليل والنهار ومن شر كل طارق يطرق إلا طارقا يطرق بخير يا رحمن' WHERE id = 2060;
UPDATE contents SET body = '١٦٢- اللهُمَّ أَلِّفْ بين قلوبِنا، وأصلِحْ ذاتَ بينِنا، واهْدِنا سُبُلَ السَّلامِ، ونَجِّنا مِنَ الظُّلُماتِ إلى النُّورِ، وجَنِّبْنا الفواحِشَ؛ ما ظَهَرَ مِنْها، وما بطنَ، وبارِكْ لنا في أسماعِنا، وأبصارِنا، وقلوبِنا، وأزواجِنا، وذُرِّيَّاتِنا، وتُبْ عَلَيْنَا، إنَّكَ أنتَ التوَّابُ الرَّحيمُ، واجعلْنا شاكرِينَ لنعمتِكَ، مُثْنِينَ بها عَلَيْكَ، قابِلينَ لها، وأَتْمِمْها علينا.', search = '١٦٢- اللهم ألف بين قلوبنا وأصلح ذات بيننا واهدنا سبل السلام ونجنا من الظلمات إلى النور وجنبنا الفواحش ما ظهر منها وما بطن وبارك لنا في أسماعنا وأبصارنا وقلوبنا وأزواجنا وذرياتنا وتب علينا إنك أنت التواب الرحيم واجعلنا شاكرين لنعمتك مثنين بها عليك قابلين لها وأتممها علينا' WHERE id = 2061;
UPDATE contents SET body = '١٦٣- اللهُمَّ إنِّي أعوذُ بِكَ من جارِ السُّوءِ، ومن زوجٍ تُشَيِّبُني قبلَ المشيب، ومن ولَدٍ يكونُ عليَّ رَبًّا، ومن مالٍ يكونُ عَلَيَّ عذابًا، ومن خليلٍ ماكرٍ عينُه تراني، وقلبُه يَرْعاني؛ إن رأى حَسَنَةً دفَنَها، وإذا رأى سيئةً أذاعَها.', search = '١٦٣- اللهم إني أعوذ بك من جار السوء ومن زوج تشيبني قبل المشيب ومن ولد يكون علي ربا ومن مال يكون علي عذابا ومن خليل ماكر عينه تراني وقلبه يرعاني إن رأى حسنة دفنها وإذا رأى سيئة أذاعها' WHERE id = 2062;
UPDATE contents SET body = '١٦٤- اللهُمَّ صَلِّ على محمدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ مُحَمَّدٍ، كما بارَكْتَ على إبراهيمَ، وعلى آلِ إبراهيم.', search = '١٦٤- اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم' WHERE id = 717;
