QuranText[(37:180:182)]', search = '١٦٥- 37180182' WHERE id = 2063;
UPDATE contents SET body = '١٦٦- اللَّهُمَّ اجعل ﴿ لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا ﴾', search = '١٦٦- اللهم اجعل ﴿ لنا من لدنك وليا وٱجۡعل لنا من لدنك نصيرا ﴾' WHERE id = 2064;
UPDATE contents SET body = '١٦٧- لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمدُ، وهُوَ على كل شيءٍ قديرٌ، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبدُ إلا إيَّاه، له النِّعمةُ، وله الفضلُ، وله الثناءُ الحَسَنُ، لا إله إلا الله، مُخلِصِين له الدينَ، ولو كَرِهَ الكافرون.', search = '١٦٧- لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير لا حول ولا قوة إلا بالله لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن لا إله إلا الله مخلصين له الدين ولو كره الكافرون' WHERE id = 2065;
UPDATE contents SET body = '١٦٨- اللَّهُمَّ رَبَّ السماواتِ وربَّ الأرضِ وربَّ العرشِ العظيمِ، ربَّنا وربَّ كُلِّ شيءٍ، فالِقَ الحَبِّ والنَّوى، مُنْزِلَ التوراةِ والإنجيلِ والفُرْقانِ، أعوذ بك من شرِّ كُلِّ ذي شرٍّ أنت آخِذٌ بناصيته، أنت الأوَّلُ فليس قَبْلَكَ شيءٌ، وأنت الآخِرُ فليس بعدَكَ شيء، وأنت الظاهرُ فليس فوقَكَ شيء، وأنت الباطنُ فليس دُونَكَ شيء، اقْضِ عَنَّا الدَّيْنَ، وأَغْنِنا من الفقر.', search = '١٦٨- اللهم رب السماوات ورب الأرض ورب العرش العظيم ربنا ورب كل شيء فالق الحب والنوى منزل التوراة والإنجيل والفرقان أعوذ بك من شر كل ذي شر أنت آخذ بناصيته أنت الأول فليس قبلك شيء وأنت الآخر فليس بعدك شيء وأنت الظاهر فليس فوقك شيء وأنت الباطن فليس دونك شيء اقض عنا الدين وأغننا من الفقر' WHERE id = 2066;
UPDATE contents SET body = '١٦٩- ﴿ رَّبِّ زِدۡنِي عِلۡمٗا ﴾', search = '١٦٩- ﴿ رب زدۡني علۡما ﴾' WHERE id = 648;
UPDATE contents SET body = '١٧٠- اللهم فَقِّهْني في الدِّين، وعَلِّمْني التأويل.', search = '١٧٠- اللهم فقهني في الدين وعلمني التأويل' WHERE id = 2067;
UPDATE contents SET body = '١٧١- اللهم إني أسألك علمًا نافعًا، وأعوذ بك من علمٍ لا ينفع.', search = '١٧١- اللهم إني أسألك علما نافعا وأعوذ بك من علم لا ينفع' WHERE id = 656;
UPDATE contents SET body = '١٧٢- اللهم انفعني بما عَلَّمْتَنِي، وعَلِّمْنِي ما ينفعُنِي، وَزِدْنِي عِلْمًا.', search = '١٧٢- اللهم انفعني بما علمتني وعلمني ما ينفعني وزدني علما' WHERE id = 2068;
UPDATE contents SET body = '١٧٣- اللهم اهدِني وَسَدِّدْني.', search = '١٧٣- اللهم اهدني وسددني' WHERE id = 858;
UPDATE contents SET body = '١٧٤- الحمدُ لله الذي كَفاني وآواني، وأطعَمَني وأسْقَاني، والذي مَنَّ عَلَيَّ فأَفضَلَ، والذي أعطاني فأَجْزَلَ، الحمدُ للهِ على كُلِّ حالٍ، اللهم ربَّ كُلِّ شيءٍ ومَلِيكَه، وإلهَ كُلِّ شيءٍ، أعوذُ بك من النار.', search = '١٧٤- الحمد لله الذي كفاني وآواني وأطعمني وأسقاني والذي من علي فأفضل والذي أعطاني فأجزل الحمد لله على كل حال اللهم رب كل شيء ومليكه وإله كل شيء أعوذ بك من النار' WHERE id = 2069;
UPDATE contents SET body = '١٧٥- اللهم إنا نستعينُك ونستغفِرُك، ولا نَكْفُرُكَ، ونؤمن بك، ونَخْلَعُ مَنْ يَفْجُرُكَ، اللهم إياك نعبد، ولك نصلي ونسجد، وإليك نسعى ونَحْفِدُ، نرجو رحمتك ونخشى عذابَك، إنَّ عذابَكَ الجِدَّ بالكُفارِ مُلْحِق.
اللهم عَذِّبِ الْكَفَرَةَ الذين يَصُدُّونَ عن سبيلِك، ويُكذِّبونَ رُسُلَك، ويُقاتِلون أولياءك، ولا يؤمنون بوعدِك، وخالِفْ بين كلمتِهم، وأَلْقِ في قلوبهم الرُّعبَ، وألقِ عليهم رِجْزَكَ وعذابَك، إلهَ الحقِّ.
اللهم اغفر للمؤمنين والمؤمناتِ، والمسلمينَ والمسلماتِ، وأصلِحْ ذات بينِهم، وأَلِّفْ بين قلوبهم، واجعلْ في قلوبهم الإيمانَ والحكمةَ، وثَبِّتْهُم على مِلَّةِ رسولِ اللهِ ﷺ، وأَوْزِعْهُمْ أن يُوفُوا بعهدِكَ الذي عاهدتَهم عليه، وانصُرْهُم على عدوِّكَ وعدوِّهم، إلَهَ الحقِّ، واجعلنا منهم.', search = '١٧٥- اللهم إنا نستعينك ونستغفرك ولا نكفرك ونؤمن بك ونخلع من يفجرك اللهم إياك نعبد ولك نصلي ونسجد وإليك نسعى ونحفد نرجو رحمتك ونخشى عذابك إن عذابك الجد بالكفار ملحق اللهم عذب الكفرة الذين يصدون عن سبيلك ويكذبون رسلك ويقاتلون أولياءك ولا يؤمنون بوعدك وخالف بين كلمتهم وألق في قلوبهم الرعب وألق عليهم رجزك وعذابك إله الحق اللهم اغفر للمؤمنين والمؤمنات والمسلمين والمسلمات وأصلح ذات بينهم وألف بين قلوبهم واجعل في قلوبهم الإيمان والحكمة وثبتهم على ملة رسول الله وأوزعهم أن يوفوا بعهدك الذي عاهدتهم عليه وانصرهم على عدوك وعدوهم إله الحق واجعلنا منهم' WHERE id = 2070;
UPDATE contents SET body = '١٧٦- اللهم اجعلْ علينا صلاةَ قومٍ أبرارٍ، يقومون الليلَ، ويصومونَ النهارَ، ليسوا بِأَثَمَةٍ ولا فُجَّارٍ.', search = '١٧٦- اللهم اجعل علينا صلاة قوم أبرار يقومون الليل ويصومون النهار ليسوا بأثمة ولا فجار' WHERE id = 2071;
UPDATE contents SET body = '١٧٧- ربَّنا آتنا في الدنيا حسنةً، وفي الآخِرَةِ حسنةً، وَقِنَا عذابَ النار.', search = '١٧٧- ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار' WHERE id = 2072;
UPDATE contents SET body = '١٧٨- اللهم اغفر لي ذنوبي وخطاياي كُلَّها، اللهم أَنْعِشْني، واجْبُرْني، واهدني لصالحِ الأعمالِ والأخلاق، فإنه لا يَهْدِي لصالحِها، ولا يَصْرِفُ سَيِّئَها إلا أنت.', search = '١٧٨- اللهم اغفر لي ذنوبي وخطاياي كلها اللهم أنعشني واجبرني واهدني لصالح الأعمال والأخلاق فإنه لا يهدي لصالحها ولا يصرف سيئها إلا أنت' WHERE id = 772;
UPDATE contents SET body = '١٧٩- اللهم إني أعوذ بك من فتنةِ النار، وعذابِ النار، ومن شرِّ الغِنى والفقر.', search = '١٧٩- اللهم إني أعوذ بك من فتنة النار وعذاب النار ومن شر الغنى والفقر' WHERE id = 797;
UPDATE contents SET body = '١٨٠- اللهم اسْتُرْ عَوْرَتي، وآمِن رَوْعَتِي، واقْضِ عَنِّي دَيْني.', search = '١٨٠- اللهم استر عورتي وآمن روعتي واقض عني ديني' WHERE id = 729;
UPDATE contents SET body = '١٨١- اللهم رحمتَك أرجو، فلا تَكِلْني إلى نفسي طَرْفَةَ عينٍ، وأَصْلِحْ لي شأني كلَّه، لا إله إلا أنت.', search = '١٨١- اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين وأصلح لي شأني كله لا إله إلا أنت' WHERE id = 794;
UPDATE contents SET body = '١٨٢- اللهم إنا نعوذ بك من شرور أنفسِنا وسيئاتِ أعمالنا.', search = '١٨٢- اللهم إنا نعوذ بك من شرور أنفسنا وسيئات أعمالنا' WHERE id = 2073;
UPDATE contents SET body = '١٨٣- اللهُمَّ إني أسألُكَ إيمانًا لا يرتدُّ، ونعيمًا لا ينفدُ، ومُرافقةَ نبيِّكَ محمدٍ ﷺ في أعلى جَنَّةِ الخُلْد.', search = '١٨٣- اللهم إني أسألك إيمانا لا يرتد ونعيما لا ينفد ومرافقة نبيك محمد في أعلى جنة الخلد' WHERE id = 2074;
UPDATE contents SET body = '١٨٤- اللهُمَّ صَلِّ على محمدٍ وعلى آلِ محمدٍ، كما صلَّيتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيدٌ، اللهُمَّ بارِكْ على محمدٍ وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد.', search = '١٨٤- اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد' WHERE id = 860;
-- title 90
UPDATE contents SET body = '١٨٥- ﴿ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ ﴾', search = '١٨٥- ﴿ أعوذ بٱلله أنۡ أكون من ٱلۡجهلين ﴾' WHERE id = 2075;
UPDATE contents SET body = '١٨٦- ﴿ رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا ﴾', search = '١٨٦- ﴿ رب أدۡخلۡني مدۡخل صدۡق وأخۡرجۡني مخۡرج صدۡق وٱجۡعل لي من لدنك سلۡطنا نصيرا ﴾' WHERE id = 630;
UPDATE contents SET body = '١٨٧- ﴿ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا ﴾', search = '١٨٧- ﴿ عسى أن يهۡدين ربي لأقۡرب منۡ هذا رشدا ﴾' WHERE id = 2076;
UPDATE contents SET body = '١٨٨- ﴿ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ﴾', search = '١٨٨- ﴿ لئن لمۡ يهۡدني ربي لأكونن من ٱلۡقوۡم ٱلضالين ﴾' WHERE id = 2077;
UPDATE contents SET body = '١٨٩- ﴿ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴾', search = '١٨٩- ﴿ ربنا أتۡممۡ لنا نورنا وٱغۡفرۡ لناۖ إنك على كل شيۡء قدير ﴾' WHERE id = 711;
UPDATE contents SET body = '١٩٠- اللهم اجعل في قلبي نورًا، وفي لساني نورًا، واجعل في سمعي نورًا، واجعل في بصري نورًا، واجعلْ مِن تحتي نورًا، واجعل من فوقي نورًا، وعن يميني نورًا، وعن يساري نورًا، واجعل أمامي نورًا، واجعل خَلْفي نورًا، واجعل في نفسي نورًا، وأعْظِمْ لي نورًا.', search = '١٩٠- اللهم اجعل في قلبي نورا وفي لساني نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من تحتي نورا واجعل من فوقي نورا وعن يميني نورا وعن يساري نورا واجعل أمامي نورا واجعل خلفي نورا واجعل في نفسي نورا وأعظم لي نورا' WHERE id = 2078;
UPDATE contents SET body = '١٩١- الحمد لله حمدًا كثيرًا طيبًا مباركًا فيه.', search = '١٩١- الحمد لله حمدا كثيرا طيبا مباركا فيه' WHERE id = 2079;
UPDATE contents SET body = '١٩٢- لا إله إلا اللهُ العظيمُ الحليم، لا إله إلا اللهُ ربُّ العرشِ العظيم، لا إله إلا اللهُ ربُّ السماواتِ والأرض، لا إله إلا اللهُ ربُّ العرشِ الكريم.', search = '١٩٢- لا إله إلا الله العظيم الحليم لا إله إلا الله رب العرش العظيم لا إله إلا الله رب السماوات والأرض لا إله إلا الله رب العرش الكريم' WHERE id = 605;
UPDATE contents SET body = '١٩٣- ربنا لك الحمدُ، مِلْءَ السماوات، ومِلْءَ الأرضِ، ومِلْءَ ما بينهما، ومِلْءَ مَا شِئْتَ من شيءٍ بَعْدُ، أَهْلَ الثناءِ والمجدِ، أَحَقُّ ما قال العبدُ، وكُلُّنا لك عبد، اللهم لا مانعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ مِنكَ الجَدُّ.', search = '١٩٣- ربنا لك الحمد ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد' WHERE id = 2080;
UPDATE contents SET body = '١٩٤- اللهم إني أسألك بأن لك الحمدَ، لا إله إلا أنت وحدك لا شريك لك، المنانُ، يا بديعَ السماواتِ والأرض، يا ذا الجلالِ والإكرام، يا حيُّ يا قيُّومُ، إني أسألك الجنةَ، وأعوذُ بك من النار.', search = '١٩٤- اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار' WHERE id = 650;
UPDATE contents SET body = '١٩٥- سبحانك اللهم ربَّنا وبحمدك، اللهم اغفر لي.', search = '١٩٥- سبحانك اللهم ربنا وبحمدك اللهم اغفر لي' WHERE id = 2081;
UPDATE contents SET body = '١٩٦- اللهم اغسل خطاياي بماءِ الثَّلجِ والبَرَدِ، ونَقِّ قلبي من الخطايا كما نقَّيْتَ الثوبَ الأبيضَ مِنَ الدَّنَسِ.', search = '١٩٦- اللهم اغسل خطاياي بماء الثلج والبرد ونق قلبي من الخطايا كما نقيت الثوب الأبيض من الدنس' WHERE id = 2082;
UPDATE contents SET body = '١٩٧- اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولَّني فيمن توليت، وبارك لي فيما أعطيتَ، وقِني شرَّ ما قضيت، فإنك تقضي ولا يُقضى عليك، وإنه لا يَذِلُّ مَنْ وَالَيْتَ، ولا يَعِزُّ من عاديت، تباركْتَ رَبَّنا وتعاليتَ، لا مَنْجا منك إلا إليك.', search = '١٩٧- اللهم اهدني فيمن هديت وعافني فيمن عافيت وتولني فيمن توليت وبارك لي فيما أعطيت وقني شر ما قضيت فإنك تقضي ولا يقضى عليك وإنه لا يذل من واليت ولا يعز من عاديت تباركت ربنا وتعاليت لا منجا منك إلا إليك' WHERE id = 2083;
UPDATE contents SET body = '١٩٨- اللهم إني أسألك الفِرْدَوْسَ الأعلى من الجنة.', search = '١٩٨- اللهم إني أسألك الفردوس الأعلى من الجنة' WHERE id = 658;
UPDATE contents SET body = '١٩٩- اللهم أَعِذْني من عذابٍ في النار، وعذابٍ في القبر.', search = '١٩٩- اللهم أعذني من عذاب في النار وعذاب في القبر' WHERE id = 2084;
UPDATE contents SET body = '٢٠٠- اللهم إني أسألك العافيةَ واليقين.', search = '٢٠٠- اللهم إني أسألك العافية واليقين' WHERE id = 2085;
UPDATE contents SET body = '٢٠١- يا مُقَلِّبَ القلوبِ ثَبِّتْ قلبي على دِينك.', search = '٢٠١- يا مقلب القلوب ثبت قلبي على دينك' WHERE id = 859;
UPDATE contents SET body = '٢٠٢- يا وليَّ الإسلامِ وأهلِه، ثَبِّتْني به حتى ألقاك.', search = '٢٠٢- يا ولي الإسلام وأهله ثبتني به حتى ألقاك' WHERE id = 2086;
UPDATE contents SET body = '٢٠٣- اللهم مَتِّعْني بسمعي وبصري، واجعلْهُما الوارِثَ مِنِّي، وانْصُرْني على مَن ظلمني، وخُذْ منه بثأري.', search = '٢٠٣- اللهم متعني بسمعي وبصري واجعلهما الوارث مني وانصرني على من ظلمني وخذ منه بثأري' WHERE id = 804;
UPDATE contents SET body = '٢٠٤- اللهم إني أعوذ بك من شرِّ جارِ السُّوءِ في دارِ المُقام.', search = '٢٠٤- اللهم إني أعوذ بك من شر جار السوء في دار المقام' WHERE id = 731;
UPDATE contents SET body = '٢٠٥- اللهم لا سَهْلَ إلا ما جعلتَهُ سهلًا، وأنت تجعلُ الحَزْنَ إذا شئتَ سَهْلًا.', search = '٢٠٥- اللهم لا سهل إلا ما جعلته سهلا وأنت تجعل الحزن إذا شئت سهلا' WHERE id = 2087;
UPDATE contents SET body = '٢٠٦- أعوذ بالله أن أكون في نفسي عظيمًا، وعند الله صغيرًا.', search = '٢٠٦- أعوذ بالله أن أكون في نفسي عظيما وعند الله صغيرا' WHERE id = 2088;
UPDATE contents SET body = '٢٠٧- اللهم ارزقني حُبَّك، وحُبَّ مَن ينفعُني حُبُّه عِندك، اللهم ما رَزَقتني مما أُحِبُّ؛ فاجعلْه قُوةً لي فيما تُحِب، اللهم وما زَوَيْتَ عني مما أُحِبُّ، فاجعلْه فَراغًا لي فيما تُحِبُّ.', search = '٢٠٧- اللهم ارزقني حبك وحب من ينفعني حبه عندك اللهم ما رزقتني مما أحب فاجعله قوة لي فيما تحب اللهم وما زويت عني مما أحب فاجعله فراغا لي فيما تحب' WHERE id = 2089;
UPDATE contents SET body = '٢٠٨- تَمَّ نورُكَ فهديتَ فلك الحمد، وعَظُمَ حِلْمُكَ فعفوتَ فلك الحمد، وبسطتَ يدَكَ فأعطيتَ فلك الحمد، ربَّنا وجهُكَ أكرمُ الوجوهِ، وجاهُكَ خيرُ الجاهِ، وعَطِيَّتُكَ أفضلُ العَطِيَّة، وأهنؤها، تُطاعُ رَبَّنَا فَتَشْكُرُ، وتُعصَى ربنا فتغفِر، تُجيبُ المضْطَرَّ، وتكشِفُ الضُّرَّ، وتَشْفي السقيمَ، وتُنَجِّي مِنَ الكَرْبِ، وتقبلُ التوبةَ، وتغفر الذنبَ لمن شِئتَ، لا يَجْزِي بآلائك أحدٌ، ولا يُحصِي نَعْماءَكَ قولُ قائل.', search = '٢٠٨- تم نورك فهديت فلك الحمد وعظم حلمك فعفوت فلك الحمد وبسطت يدك فأعطيت فلك الحمد ربنا وجهك أكرم الوجوه وجاهك خير الجاه وعطيتك أفضل العطية وأهنؤها تطاع ربنا فتشكر وتعصى ربنا فتغفر تجيب المضطر وتكشف الضر وتشفي السقيم وتنجي من الكرب وتقبل التوبة وتغفر الذنب لمن شئت لا يجزي بآلائك أحد ولا يحصي نعماءك قول قائل' WHERE id = 2090;
UPDATE contents SET body = '٢٠٩- اللهم صَلِّ على محمدٍ النَّبيِّ الأُمِّيِّ، وعلى آلِ محمد، كما صليتَ على آل إبراهيمَ، وبارِك على محمدٍ النبيِّ الأُمِّيِّ وعلى آلِ محمد، كما باركتَ على آل إبراهيمَ في العالمين، إنك حميد مجيد.', search = '٢٠٩- اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد' WHERE id = 636;
