UPDATE contents SET body = '٢١٠- ﴿ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴾', search = '٢١٠- ﴿ ربنا تقبلۡ مناۖ إنك أنت ٱلسميع ٱلۡعليم ﴾' WHERE id = 828;
UPDATE contents SET body = '٢١١- ﴿ وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴾', search = '٢١١- ﴿ وتبۡ عليۡناۖ إنك أنت ٱلتواب ٱلرحيم ﴾' WHERE id = 2091;
UPDATE contents SET body = '٢١٢- ﴿ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ﴾', search = '٢١٢- ﴿ ربنا ءاتنا في ٱلدنۡيا حسنة وفي ٱلۡأخرة حسنة وقنا عذاب ٱلنار ﴾' WHERE id = 829;
UPDATE contents SET body = '٢١٣- ﴿ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴾ [الزمر: ٤٦]، اهدِني لما اختُلِفَ فيه من الحقِّ بإذنِكَ، إنَّك تهدي مَنْ تشاءُ إلى صراطٍ مستقيم.', search = '٢١٣- ﴿ ٱللهم فاطر ٱلسموت وٱلۡأرۡض علم ٱلۡغيۡب وٱلشهدة أنت تحۡكم بيۡن عبادك في ما كانوا فيه يخۡتلفون ﴾ الزمر ٤٦ اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم' WHERE id = 2092;
UPDATE contents SET body = '٢١٤- ﴿ رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ﴾', search = '٢١٤- ﴿ رب ٱغۡفرۡ وٱرۡحمۡ وأنت خيۡر ٱلرحمين ﴾' WHERE id = 689;
UPDATE contents SET body = '٢١٥- ﴿ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', search = '٢١٥- ﴿ ربنا ٱغۡفرۡ لنا ذنوبنا وإسۡرافنا في أمۡرنا وثبتۡ أقۡدامنا وٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾' WHERE id = 607;
UPDATE contents SET body = '٢١٦- ﴿ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ﴾', search = '٢١٦- ﴿ ربنا ٱغۡفرۡ لنا ولإخۡوننا ٱلذين سبقونا بٱلۡإيمن ولا تجۡعلۡ في قلوبنا غلا للذين ءامنوا ربنا إنك رءوف رحيم ﴾' WHERE id = 748;
UPDATE contents SET body = '٢١٧- ﴿ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ ٨٥ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', search = '٢١٧- ﴿ على ٱلله توكلۡنا ربنا لا تجۡعلۡنا فتۡنة للۡقوۡم ٱلظلمين ٨٥ ونجنا برحۡمتك من ٱلۡقوۡم ٱلۡكفرين ﴾' WHERE id = 627;
UPDATE contents SET body = '٢١٨- ﴿ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ﴾', search = '٢١٨- ﴿ ربنا لا تجۡعلۡنا مع ٱلۡقوۡم ٱلظلمين ﴾' WHERE id = 608;
UPDATE contents SET body = '٢١٩- ﴿ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ﴾', search = '٢١٩- ﴿ رب نجني من ٱلۡقوۡم ٱلظلمين ﴾' WHERE id = 2093;
UPDATE contents SET body = '٢٢٠- لا إله إلا اللهُ وحدَه، أعزَّ جُنْدَه، ونصرَ عبدَه، وغَلَبَ الأحزابَ وحدَه، فلا شيءَ بعدَه.', search = '٢٢٠- لا إله إلا الله وحده أعز جنده ونصر عبده وغلب الأحزاب وحده فلا شيء بعده' WHERE id = 2094;
