UPDATE contents SET body = '٢٢٢- يا حيُّ يا قيُّومُ، برحمتِكَ أستغيثُ.', search = '٢٢٢- يا حي يا قيوم برحمتك أستغيث' WHERE id = 2096;
UPDATE contents SET body = '٢٢٣- اللهُمَّ إنِّي أسألُكَ بأنِّي أشهدُ أنَّك أنتَ الله الذي لا إله إلا أنتَ، الأحدُ الصمدُ، الذي لم يَلِد، ولم يُولد، ولم يكن له كُفُوًا أحدٌ، أن تغفِرَ لي ذُنُوبي، إنَّك أنتَ الغفور الرحيم.', search = '٢٢٣- اللهم إني أسألك بأني أشهد أنك أنت الله الذي لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم' WHERE id = 2097;
UPDATE contents SET body = '٢٢٤- اللهم لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، ومِلْءَ ما شِئتَ مِن شيءٍ بعدُ، اللهم طَهِّرْني بالثلج والبَرَد والماء البارد، اللهم طَهِّرني من الذنوب والخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَس.', search = '٢٢٤- اللهم لك الحمد ملء السماوات وملء الأرض وملء ما شئت من شيء بعد اللهم طهرني بالثلج والبرد والماء البارد اللهم طهرني من الذنوب والخطايا كما ينقى الثوب الأبيض من الدنس' WHERE id = 2098;
UPDATE contents SET body = '٢٢٥- اللهمَّ إني أعوذُ بِكَ من غَلَبَةِ الدَّيْنِ، وغلبةِ العَدُوِّ، وشماتةِ الأعداء.', search = '٢٢٥- اللهم إني أعوذ بك من غلبة الدين وغلبة العدو وشماتة الأعداء' WHERE id = 776;
UPDATE contents SET body = '٢٢٦- اللهم إني أعوذُ بِكَ من مُنكراتِ الأخلاقِ والأعمالِ والأهواء.', search = '٢٢٦- اللهم إني أعوذ بك من منكرات الأخلاق والأعمال والأهواء' WHERE id = 795;
UPDATE contents SET body = '٢٢٧- اللهم إنا نسألُكَ أن تستُرَ عوراتِنا، وتُؤَمِّنَ رَوْعاتِنا.', search = '٢٢٧- اللهم إنا نسألك أن تستر عوراتنا وتؤمن روعاتنا' WHERE id = 696;
UPDATE contents SET body = '٢٢٨- اللهمَّ إنِّي أعوذُ بِكَ من جَهْدِ البلاءِ، ودَرَكِ الشقاءِ، وسُوءِ القضاءِ، وشماتةِ الأعداء.', search = '٢٢٨- اللهم إني أعوذ بك من جهد البلاء ودرك الشقاء وسوء القضاء وشماتة الأعداء' WHERE id = 655;
UPDATE contents SET body = '٢٢٩- اللهم اغفِر لي ذنبي، ووَسِّعْ لي في داري، وبارِكْ لي في رِزقي.', search = '٢٢٩- اللهم اغفر لي ذنبي ووسع لي في داري وبارك لي في رزقي' WHERE id = 2099;
UPDATE contents SET body = '٢٣٠- اللهم إني أعوذُ بِكَ من القسوةِ، والغفلةِ، والعَيْلَةِ، والذِّلَّةِ، والمَسْكَنَةِ، وأعوذُ بِكَ من الفقرِ، والكفرِ، والفسوقِ، والشقاقِ، والسُّمعةِ والرياءِ، وأعوذُ بِكَ من الصَّمَمِ والبَكَمِ، والجنونِ والجُذامِ، وسَيِّئِ الأسقام.', search = '٢٣٠- اللهم إني أعوذ بك من القسوة والغفلة والعيلة والذلة والمسكنة وأعوذ بك من الفقر والكفر والفسوق والشقاق والسمعة والرياء وأعوذ بك من الصمم والبكم والجنون والجذام وسيئ الأسقام' WHERE id = 775;
UPDATE contents SET body = '٢٣١- اللهم إني أعوذُ بِكَ من البَرَصِ والجنونِ والجُذَامِ، ومن سَيِّئِ الأسقام.', search = '٢٣١- اللهم إني أعوذ بك من البرص والجنون والجذام ومن سيئ الأسقام' WHERE id = 730;
UPDATE contents SET body = '٢٣٢- اللهم إني أعوذُ بِك من الهَدْمِ، وأعوذ بك من التردِّي، وأعوذُ بِكَ من الغَرَقِ، والحَرَقِ، والهَرَمِ، وأعوذُ بِكَ أن يَتَخَبَّطَنِيَ الشيطانُ عند الموتِ، وأعوذُ بِكَ أن أموتَ في سبيلِكَ مُدبِرًا، وأعوذُ بِكَ أنْ أموتَ لَدِيغًا.', search = '٢٣٢- اللهم إني أعوذ بك من الهدم وأعوذ بك من التردي وأعوذ بك من الغرق والحرق والهرم وأعوذ بك أن يتخبطني الشيطان عند الموت وأعوذ بك أن أموت في سبيلك مدبرا وأعوذ بك أن أموت لديغا' WHERE id = 801;
UPDATE contents SET body = '٢٣٣- اللهم اغفِرْ لنا وارحمنا، وبارِكْ علينا، ووَسِّعْ علينا في أرزاقِنا.', search = '٢٣٣- اللهم اغفر لنا وارحمنا وبارك علينا ووسع علينا في أرزاقنا' WHERE id = 2100;
UPDATE contents SET body = '٢٣٤- اللهم انفعني بما عَلَّمْتَني، وعَلِّمْني ما ينفعُني، وارزقني علمًا تنفعُني به.', search = '٢٣٤- اللهم انفعني بما علمتني وعلمني ما ينفعني وارزقني علما تنفعني به' WHERE id = 2101;
UPDATE contents SET body = '٢٣٥- اللهم رَبَّ جبرائيلَ وميكائيلَ، وربَّ إسرافيلَ، أعوذُ بك من حَرِّ النار، وعذابِ القبر.', search = '٢٣٥- اللهم رب جبرائيل وميكائيل ورب إسرافيل أعوذ بك من حر النار وعذاب القبر' WHERE id = 798;
UPDATE contents SET body = '٢٣٦- اللهم إني أسألُكَ تَمامَ النِّعمة.', search = '٢٣٦- اللهم إني أسألك تمام النعمة' WHERE id = 2102;
UPDATE contents SET body = '٢٣٧- اللهم إني أسألك الجنة. [ثلاثًا]', search = '٢٣٧- اللهم إني أسألك الجنة ثلاثا' WHERE id = 850;
UPDATE contents SET body = 'اللهم إنِّي أعوذُ بكَ من النار. [ثلاثًا]', search = 'اللهم إني أعوذ بك من النار ثلاثا' WHERE id = 851;
UPDATE contents SET body = '٢٣٨- اللهُمَّ مُنَّ عَلَيْنَا، وَقِنَا عذابَ السَّموم، إنَّك أنتَ البَرُّ الرَّحيم.', search = '٢٣٨- اللهم من علينا وقنا عذاب السموم إنك أنت البر الرحيم' WHERE id = 2103;
UPDATE contents SET body = '٢٣٩- اللهم صَلِّ على محمدٍ عبدِكَ ورسولِكَ النبيِّ الأُمِّيِّ، وعلى آلِ محمدٍ وأزواجِهِ وذُرِّيَّتِه، كما صَلَّيْتَ على إبراهيمَ وعلى آلِ إبراهيم، وبارِكْ على محمدٍ النبيِّ الأُمِّي، وعلى آلِ محمدٍ وأزواجِهِ وذُرِّيَّتِهِ، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ في العالمين، إنَّكَ حميدٌ مجيد.', search = '٢٣٩- اللهم صل على محمد عبدك ورسولك النبي الأمي وعلى آل محمد وأزواجه وذريته كما صليت على إبراهيم وعلى آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد وأزواجه وذريته كما باركت على إبراهيم وعلى آل إبراهيم في العالمين إنك حميد مجيد' WHERE id = 777;
UPDATE contents SET body = '٢٤٠- سبحان الله وبحمدِه، سبحانك اللهم وبحمدك، أشهدُ أن لا إله إلا أنتَ، أستغفِرُك، وأتوبُ إليك.', search = '٢٤٠- سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك' WHERE id = 2104;
