UPDATE contents SET body = '١- ﴿ رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ٩٧ وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ ﴾', search = '١- ﴿ رب أعوذ بك منۡ همزت ٱلشيطين ٩٧ وأعوذ بك رب أن يحۡضرون ﴾' WHERE id = 827;
UPDATE contents SET body = '٢- أعوذ بالله السميع العليم من الشيطان الرجيم.', search = '٢- أعوذ بالله السميع العليم من الشيطان الرجيم' WHERE id = 824;
