QuranText[(1:1:7)]', search = '٣- 117' WHERE id = 826;
UPDATE contents SET body = '٤- ﴿ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴾', search = '٤- ﴿ سمعۡنا وأطعۡناۖ غفۡرانك ربنا وإليۡك ٱلۡمصير ﴾' WHERE id = 830;
UPDATE contents SET body = '٥- ﴿ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', search = '٥- ﴿ ربنا لا تؤاخذۡنا إن نسينا أوۡ أخۡطأۡناۚ ربنا ولا تحۡملۡ عليۡنا إصۡرا كما حملۡتهۥ على ٱلذين من قبۡلناۚ ربنا ولا تحملۡنا ما لا طاقة لنا بهۦۖ وٱعۡف عنا وٱغۡفرۡ لنا وٱرۡحمۡناۚ أنت موۡلىنا فٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾' WHERE id = 831;
UPDATE contents SET body = '٦- اللهم إني أسألك يا اللهُ الواحدُ الأحدُ الصمدُ، الذي لم يلد، ولم يُولَدْ، ولم يكن له كُفُوًا أحدٌ، أن تغفر لي ذُنُوبي، إنك أنت الغفورُ الرحيم.', search = '٦- اللهم إني أسألك يا الله الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم' WHERE id = 1983;
UPDATE contents SET body = '٧- اللهم أنت ربي، لا إله إلا أنت خلقتَني، وأنا عبدُكَ، وأنا على عهدِكَ ووعدِكَ ما استطعتُ، أعوذ بك من شَرِّ ما صنعتُ، أبوءُ لك بنعمتِكَ عَلَيَّ، وأبوءُ بذنبي فاغفر لي، فإنه لا يغفرُ الذنوبَ إلا أنت.', search = '٧- اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت' WHERE id = 835;
UPDATE contents SET body = '٨- اللهم اغفر لِحَيِّنا وَمَيِّتِنا، وشاهدِنا وغائبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنَا وأُنثَانا، اللهم من أَحْيَيْتَهُ مِنَّا، فَأَحْيِهِ على الإسلام، ومن توفيتَهُ مِنَّا، فَتَوَفَّهُ على الإيمان.', search = '٨- اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا اللهم من أحييته منا فأحيه على الإسلام ومن توفيته منا فتوفه على الإيمان' WHERE id = 1984;
UPDATE contents SET body = '٩-
QuranText[(3:8:8)]', search = '٩- 388' WHERE id = 832;
UPDATE contents SET body = '١٠- اللهم لك أسلمتُ، وبك آمنتُ، وعليك تَوَكَّلْتُ، وإليك أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللهم إني أعوذ بِعِزَّتِكَ –لا إله إلا أنت– أن تُضِلَّني، أنت الحيُّ الذي لا يموت، والجنُّ والإنسُ يموتون.', search = '١٠- اللهم لك أسلمت وبك آمنت وعليك توكلت وإليك أنبت وبك خاصمت اللهم إني أعوذ بعزتك –لا إله إلا أنت– أن تضلني أنت الحي الذي لا يموت والجن والإنس يموتون' WHERE id = 652;
UPDATE contents SET body = '١١- اللهم إنا نسألُكَ أن تُجَدِّدَ الإيمانَ في قلوبنا.', search = '١١- اللهم إنا نسألك أن تجدد الإيمان في قلوبنا' WHERE id = 651;
UPDATE contents SET body = '١٢- اللهم مُصَرِّفَ القلوبِ، صَرِّفْ قلوبَنا على طاعتك.', search = '١٢- اللهم مصرف القلوب صرف قلوبنا على طاعتك' WHERE id = 716;
UPDATE contents SET body = '١٣- اللَّهُمَّ ﴿ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ ﴾', search = '١٣- اللهم ﴿ فاطر ٱلسموت وٱلۡأرۡض أنت وليۦ في ٱلدنۡيا وٱلۡأخرةۖ توفني مسۡلما وألۡحقۡني بٱلصلحين ﴾' WHERE id = 1985;
UPDATE contents SET body = '١٤- اللهم إني أسألُكَ الهُدَى والسَّدَادَ.', search = '١٤- اللهم إني أسألك الهدى والسداد' WHERE id = 1986;
UPDATE contents SET body = '١٥- يا مُقَلِّبَ القُلُوبِ ثَبِّتْ قلوبَنا على دينِكَ.', search = '١٥- يا مقلب القلوب ثبت قلوبنا على دينك' WHERE id = 1987;
UPDATE contents SET body = '١٦- اللهم احفظني بالإسلام قائمًا، واحفظني بالإسلام قاعدًا، واحفظني بالإسلام راقدًا، ولا تُشْمِتْ بي عدوًّا حاسدًا، اللهم إني أسألُكَ من كل خيرٍ خزائنُه بيدك، وأعوذ بك من كل شرٍّ خزائنُه بيدك.', search = '١٦- اللهم احفظني بالإسلام قائما واحفظني بالإسلام قاعدا واحفظني بالإسلام راقدا ولا تشمت بي عدوا حاسدا اللهم إني أسألك من كل خير خزائنه بيدك وأعوذ بك من كل شر خزائنه بيدك' WHERE id = 612;
UPDATE contents SET body = '١٧- يا وليَّ الإسلامِ وأهلِهِ، مَسِّكْني الإسلامَ حتى ألقاك عليه.', search = '١٧- يا ولي الإسلام وأهله مسكني الإسلام حتى ألقاك عليه' WHERE id = 635;
UPDATE contents SET body = '١٨- اللهم حَبِّبْ إلينا الإيمانَ، وزَيِّنْهُ في قُلُوبِنَا، وَكَرِّهْ إلينا الكُفْرَ وَالْفُسُوقَ والعِصْيانَ، واجعلنا مِنَ الرَّاشِدين.', search = '١٨- اللهم حبب إلينا الإيمان وزينه في قلوبنا وكره إلينا الكفر والفسوق والعصيان واجعلنا من الراشدين' WHERE id = 1988;
UPDATE contents SET body = '١٩- اللهم إنَّك قُلْتَ: ﴿ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ ﴾ [غافر: ٦٠]، وإنَّك لا تُخلِفُ الميعادَ، وإنِّي أسألُك كما هديتَني للإسلامِ: أن لا تَنْزِعَهُ مِنِّي، حتَّى تتوفَّاني وأنا مُسلِمٌ.', search = '١٩- اللهم إنك قلت ﴿ ٱدۡعوني أسۡتجبۡ لكمۡۚ ﴾ غافر ٦٠ وإنك لا تخلف الميعاد وإني أسألك كما هديتني للإسلام أن لا تنزعه مني حتى تتوفاني وأنا مسلم' WHERE id = 1989;
UPDATE contents SET body = '٢٠- اللهم ارزقني شهادةً في سبيلِكَ، واجعل موتي في بَلَدِ رسولِكَ.', search = '٢٠- اللهم ارزقني شهادة في سبيلك واجعل موتي في بلد رسولك' WHERE id = 1990;
UPDATE contents SET body = '٢١- اللهم تَوَفَّني مَعَ الأبرارِ، ولا تُخَلِّفْني مع الأشرارِ، وأَلْحِقني بالأخيار.', search = '٢١- اللهم توفني مع الأبرار ولا تخلفني مع الأشرار وألحقني بالأخيار' WHERE id = 1991;
UPDATE contents SET body = '٢٢- اللهمَّ صَلِّ على محمدٍ، وعلى آلِ مُحَمَّدٍ، كما صَلَّيْتَ على إبراهيمَ، وعلى آلِ إبراهيم، إنَّك حميدٌ مجيد، اللهم بارِكْ على محمدٍ، وعلى آلِ محمد، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد.', search = '٢٢- اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد' WHERE id = 1992;
