UPDATE contents SET body = '٧٩- تعالى ﴿ ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ﴾', search = '٧٩- تعالى ﴿ ٱلله ٱلۡملك ٱلۡحقۖ لا إله إلا هو رب ٱلۡعرۡش ٱلۡكريم ﴾' WHERE id = 2016;
