UPDATE contents SET body = '١- في كل الأوقات والأحوال: من ليل أو نهار، وصباح ومساء، وعند النوم واليقظة، وفي السراء والضراء، والرضى والغضب، والغِنى والفقر، والصحة والمرض، في الطفولة والشباب، والشيخوخة والهَرَمِ وأرذلِ العُمُر.', search = '١- في كل الأوقات والأحوال من ليل أو نهار وصباح ومساء وعند النوم واليقظة وفي السراء والضراء والرضى والغضب والغنى والفقر والصحة والمرض في الطفولة والشباب والشيخوخة والهرم وأرذل العمر' WHERE id = 1965;
UPDATE contents SET body = '٢- ومن شرِّ كُلِّ ذي شَرٍّ من المخلوقات: كإبليسَ وجنودِه، وشياطينِ الجنِّ والإنسِ، والحاسدين، والظالمين، والسَّحَرَةِ، وأصحابِ الأهواء والبدع، وجيرانِ السُّوءِ وأصحابِ السُّوء.', search = '٢- ومن شر كل ذي شر من المخلوقات كإبليس وجنوده وشياطين الجن والإنس والحاسدين والظالمين والسحرة وأصحاب الأهواء والبدع وجيران السوء وأصحاب السوء' WHERE id = 1966;
UPDATE contents SET body = '٣- بل من شرور أنفسِنا وأهوائنا ومنكراتِ أخلاقنا، من حَواسِّنا وأعضائنا؛ كالقلب والعين واللسان والأذنِ والفَرْجِ، من أموالنا، وسيئاتِ أعمالنا؛ ما وقع منها بالفعل، وما نخافُ وقوعَه ونحذرُه.', search = '٣- بل من شرور أنفسنا وأهوائنا ومنكرات أخلاقنا من حواسنا وأعضائنا كالقلب والعين واللسان والأذن والفرج من أموالنا وسيئات أعمالنا ما وقع منها بالفعل وما نخاف وقوعه ونحذره' WHERE id = 1967;
UPDATE contents SET body = '٤- من المصائب والأقدار المؤلمة؛ كالحروب، والأوبئة، والأمراض الجسدية والنفسية.', search = '٤- من المصائب والأقدار المؤلمة كالحروب والأوبئة والأمراض الجسدية والنفسية' WHERE id = 1968;
UPDATE contents SET body = '٥- من الفتن ما ظهر منها وما بطن: لا سيما في عصر غُرْبَةِ الإسلام، وَفِتَنِ آخِرِ الزمان؛ كالدعاةِ على أبوابِ جهنمَ، وفتنةِ المسيح الدجال «شَرِّ غَائِبٍ يُنتَظَرُ».', search = '٥- من الفتن ما ظهر منها وما بطن لا سيما في عصر غربة الإسلام وفتن آخر الزمان كالدعاة على أبواب جهنم وفتنة المسيح الدجال «شر غائب ينتظر»' WHERE id = 1969;
UPDATE contents SET body = '٦- ومن مصارع السُّوءِ: كالهدم والتردِّي والغَرَقِ والحَرَقِ والزلزالِ والخسف، ومن سُوء الخاتمة عند الاحتضار، وتخبطِ الشيطان عند الموت، ومن عذاب القبر في الحياة البرزخية، ومن فتنِ وأهوالِ يومِ القيامة، وعذاب جهنمَ، أعاذنا الله منها ومن سائر الشرور.', search = '٦- ومن مصارع السوء كالهدم والتردي والغرق والحرق والزلزال والخسف ومن سوء الخاتمة عند الاحتضار وتخبط الشيطان عند الموت ومن عذاب القبر في الحياة البرزخية ومن فتن وأهوال يوم القيامة وعذاب جهنم أعاذنا الله منها ومن سائر الشرور' WHERE id = 1970;
